"use strict";exports.id=724,exports.ids=[724],exports.modules={724:(e,t,i)=>{i.d(t,{j:()=>n});let s={node:{label:"Node.js",adds:["Profile with --cpu-prof and clinic; inspect event-loop lag","Guard against blocking calls in hot paths with async worker offload"]},python:{label:"Python",adds:["Profile with py-spy and cProfile; watch the GIL on CPU-bound paths","Pin environments via lockfiles; verify wheels exist for your platforms"]},go:{label:"Go",adds:["Run pprof profiles; check goroutine leaks with goleak","Enforce vet/lint gates; keep error wrapping with %w intact"]},rust:{label:"Rust",adds:["Let the borrow checker guide design; resist RefCell escapes","Benchmark criterion suites for hot paths before optimizing"]},java:{label:"Java/JVM",adds:["Tune GC logs review into routine; watch allocation pressure","Use JFR recordings for production-safe continuous profiling"]},dotnet:{label:".NET",adds:["Review GC modes per workload type (workstation/server)","Benchmark with BenchmarkDotNet; beware allocation in loops"]}},n=[{id:"ai-engineering",label:"AI Engineering",icon:"\uD83E\uDD16",gradient:"from-violet-500 via-purple-500 to-fuchsia-500",ring:"ring-violet-500/30",text:"text-violet-400",blurb:"Ship reliable LLM systems: RAG, agents, evals, fine-tuning, and inference ops.",roles:["AI Engineers","ML Engineers","LLM App Developers","Agent Builders"],domains:[{id:"rag-pipelines",label:"RAG Pipelines",procedures:[{id:"chunking-strategy",title:"Design a chunking strategy for retrieval",level:"foundation",minutes:25,description:"Choose chunk sizes, overlaps, and structure-aware splits so retrieved context actually helps the model answer.",tags:["rag","embeddings","retrieval"],steps:["Profile source documents: length distribution, headings, tables, code blocks","Pick structural splitter first (headings/paragraphs) over fixed character cuts","Set chunk size from your model's effective context budget minus prompt overhead","Add 10-20% overlap so facts spanning boundaries survive retrieval","Attach metadata per chunk: source title, section path, date, permissions","Build 20 golden questions and measure retrieval hit-rate before scaling up"],pitfalls:["Fixed-size chunks that slice tables and lists into meaningless fragments","Chunks larger than half the context window, starving the actual answer space","No overlap, causing answers that cite half a sentence cut at a boundary"],kpis:["Recall@5 above 85% on golden set","Median chunks-per-answer under 6"]},{id:"hybrid-search",title:"Implement hybrid keyword + vector search",level:"intermediate",minutes:35,description:"Combine BM25-style lexical search with dense embeddings and fuse results so both rare terms and paraphrases are found.",tags:["rag","search","bm25"],steps:["Stand up a lexical index (BM25) alongside your vector index on the same chunks","Embed queries with the same model and distance metric used at ingestion","Retrieve top-k from both indexes with k at least double your final context size","Fuse rankings with Reciprocal Rank Fusion (RRF), k=60 as default","Optionally rerank fused candidates with a cross-encoder on top-50","A/B against pure-vector on your golden questions; keep the winner per query class"],pitfalls:["Mixing similarity metrics between ingestion and query time","Fusing raw scores instead of ranks across incompatible scales"],kpis:["Hit-rate lift over best single retriever","P95 retrieval latency under 300ms"]},{id:"eval-rag-quality",title:"Evaluate RAG answer quality automatically",level:"advanced",minutes:45,description:"Score groundedness, relevance, and completeness with judge prompts plus deterministic checks wired into CI.",tags:["evals","quality","ci"],steps:["Freeze 30-100 test questions with known-good source passages","Run deterministic checks first: citation present, answer not empty, no refusal","Use an LLM judge with rubric scores 1-5 for groundedness and relevance","Swap judge models occasionally; if two judges disagree widely, fix the rubric","Log every eval artifact: question, chunks used, answer, scores, cost, latency","Block merges when groundedness average drops more than 0.3 below baseline"],pitfalls:["Judging with the same model that generated the answer, inflating scores","Evals only run manually, drifting from production reality"],kpis:["Groundedness average 4.3+ of 5","Eval suite runtime under 10 minutes"]}]},{id:"agents",label:"AI Agents",procedures:[{id:"tool-design",title:"Design tools an agent can use reliably",level:"intermediate",minutes:40,description:"Shape tool names, parameters, descriptions, and error messages so the agent calls the right tool with valid arguments.",tags:["agents","tools","function-calling"],steps:["One tool = one verb-noun responsibility; split anything doing two jobs","Write parameter descriptions that state format and units explicitly","Return structured errors the agent can self-correct from, never stack traces","Make tools idempotent where possible; require confirmation flags for destructive ones","Cap list results and paginate instead of dumping unbounded payloads","Test with adversarial phrasings that should NOT trigger the tool"],pitfalls:["Overlapping tools forcing the model to guess between near-duplicates","Boolean success returns hiding why a call failed"],kpis:["Tool-call validity rate above 95%","Zero destructive calls without confirmation"]},{id:"agent-loop-guardrails",title:"Add guardrails to autonomous agent loops",level:"advanced",minutes:45,description:"Bound agent autonomy with step budgets, spend caps, human gates, and checkpointing so failures stay cheap and debuggable.",tags:["agents","safety","orchestration"],steps:["Set hard max-step and max-token budgets; treat exhaustion as a normal outcome","Checkpoint full state after every step so runs resume or replay cleanly","Require explicit human approval before irreversible external actions","Detect loops: identical tool+args twice means intervene or abort","Emit structured events per step for tracing and postmortems","Run a canary suite of risky tasks nightly and alert on behavior drift"],pitfalls:["Unbounded retry loops burning budget on a failing subgoal","Approving via broad allowlists instead of per-action gates"],kpis:["Mean steps-to-completion trending down","100% of destructive actions behind approval"]},{id:"multi-agent-handoffs",title:"Structure multi-agent handoffs",level:"advanced",minutes:50,description:"Split work across specialized agents with typed handoff contracts so context survives delegation without ballooning.",tags:["agents","architecture"],steps:["Give each agent one role, its own system prompt, and a minimal toolset","Define handoff payloads as typed objects: goal, constraints, artifacts, done-criteria","Pass summaries and pointers between agents, never full transcripts","Keep an orchestrator that owns retries and escalation to humans","Log which agent produced each artifact for attribution and debugging","Load-test worst-case fan-out before enabling parallel subagents"],pitfalls:["Agents debating in circles because ownership is ambiguous","Context bloat from forwarding entire conversation histories"]}]},{id:"prompt-engineering",label:"Prompt Engineering",procedures:[{id:"system-prompt-arch",title:"Architect a maintainable system prompt",level:"foundation",minutes:30,description:"Organize identity, rules, tools, and output contracts into sections that evolve without breaking behavior.",tags:["prompts","llm"],steps:["Section order: identity, capabilities, hard rules, task guidance, output format, examples","State hard rules as short imperatives; explain rationale only when it changes behavior","Put the output contract last and show one canonical example","Version the prompt like code; change one concern per revision","Keep a regression set of 15 prompts run after every edit","Delete anything that survived three revisions without effect"],pitfalls:["Conflicting rules buried mid-prompt that silently override each other","Examples contradicting the stated format"],kpis:["Regression pass rate 100% on releases","Prompt length trending down"]},{id:"few-shot-selection",title:"Select few-shot examples that move accuracy",level:"intermediate",minutes:30,description:"Choose and order examples covering edge cases so the model generalizes instead of copying surface patterns.",tags:["prompts","few-shot"],steps:["Cover each output field's edge cases once: empty, unicode, long input, ambiguity","Order examples easy-to-hard so difficulty ramps within context","Match example format byte-for-byte to the required output format","Prefer real production samples over invented ones","Rotate in failure cases you fixed, turning regressions into teachers","Measure: remove one example at a time, drop any whose removal costs nothing"],pitfalls:["Six near-identical easy examples teaching style but not judgment","Whitespace mismatches between examples and instructions"],variants:{classification:{id:"cls",label:"Classification tasks",adds:["Include one deliberately ambiguous item with the correct tie-break label","Balance classes in examples; imbalance biases predictions"]},extraction:{id:"extr",label:"Extraction tasks",adds:["Show null handling for missing fields explicitly","Demonstrate normalization: dates, currencies, units"]}}},{id:"structured-output",title:"Guarantee structured outputs from LLMs",level:"intermediate",minutes:35,description:"Get machine-parseable JSON reliably using schema-first prompting, constrained decoding, and repair loops.",tags:["json","structured-output","reliability"],steps:["Provide the JSON Schema in the prompt and ask for schema-valid output only","Prefer provider-native structured-output or function-calling modes when available","Set temperature low for extraction; reserve high temperature for ideation tasks","Validate with a strict parser; reject unknown keys and wrong types","On failure, re-ask once including the validation error verbatim","Quarantine repeated failures to a dead-letter store for rubric fixes"],pitfalls:["Parsing with regex instead of a real schema validator","Accepting markdown-fenced JSON silently breaking downstream parsers"]}]},{id:"fine-tuning-adaptation",label:"Fine-tuning & Adaptation",procedures:[{id:"dataset-prep-sft",title:"Prepare supervised fine-tuning datasets",level:"advanced",minutes:60,description:"Clean, deduplicate, and balance instruction-response pairs so fine-tuning learns behavior rather than noise.",tags:["fine-tuning","datasets","training"],steps:["Define the target behavior as 5 crisp capability statements before collecting data","Deduplicate near-identical pairs; duplicates amplify artifacts","Balance coverage across capabilities, lengths, and difficulty tiers","Hold out 3% as an untouched eval split mirroring real traffic","Scrub PII and secrets with automated scans plus human spot checks","Start LoRA-scale: 500-2000 high-quality pairs beat 50k scraped ones"],pitfalls:["Training on outputs of the same model you are tuning, compounding errors","Response style inconsistent across contributors"],kpis:["Eval-split win-rate vs base model above 70%","Zero PII findings in pre-flight scan"]},{id:"when-not-to-finetune",title:"Decide between prompting, RAG, and fine-tuning",level:"foundation",minutes:20,description:"Pick the cheapest adaptation layer that solves the problem using a decision ladder.",tags:["strategy","architecture","cost"],steps:["Try prompt engineering first: most 'model gaps' are specification gaps","If failures are missing knowledge, add retrieval, not weights","If failures are format/tone/style consistency, consider light fine-tuning","Estimate 12-month cost per option including maintenance, not just training","Prototype the winner in one week; if gains are marginal, revert to cheaper tier","Document the decision and revisit when base models jump a generation"],pitfalls:["Fine-tuning to inject facts that go stale within months","Skipping the cheap baseline entirely"]}]},{id:"inference-mlops",label:"Inference & MLOps",procedures:[{id:"latency-budgeting",title:"Budget LLM latency end to end",level:"intermediate",minutes:30,description:"Allocate milliseconds across retrieval, prompting, generation, and streaming so p95 meets product targets.",tags:["performance","latency","streaming"],steps:["Trace one real request through every hop and record percentile timings","Fix a p95 target from UX research, not infrastructure convenience","Stream tokens to first-paint; perceived latency beats raw latency","Cap retrieved context by latency cost, not just token count","Cache stable prefixes: system prompts, few-shots, static context","Alert when any hop exceeds 40% of total budget for an hour"],pitfalls:["Optimizing model choice while network hops dominate","Non-streaming endpoints behind slow proxies"]},{id:"llm-cost-controls",title:"Control LLM spend without killing quality",level:"intermediate",minutes:30,description:"Route by task complexity, cache aggressively, and enforce budgets so unit economics hold as usage grows.",tags:["cost","routing","caching"],steps:["Tag every request with feature and tenant for per-unit cost attribution","Route simple tasks to small models using a trained classifier or heuristics","Cache exact and semantic matches; measure hit-rate weekly","Compress context: prune, summarize history, cap tool outputs","Set per-key and per-tenant daily caps with graceful degradation paths","Review the top ten most expensive prompts monthly and shrink them"],pitfalls:["Premium model answering 'is this email spam?'","Semantic caches keyed too loosely, returning stale answers"]},{id:"prompt-injection-defense",title:"Defend pipelines against prompt injection",level:"advanced",minutes:40,description:"Treat all retrieved content as untrusted input: isolate instructions from data, gate actions, and fuzz continuously.",tags:["security","agents","prompt-injection"],steps:["Separate instruction and data channels structurally, not just by prose","Never grant the executor credentials beyond the current task's scope","Gate outbound actions (email, payments, deletes) behind policy checks","Strip or neutralize instruction-like patterns in retrieved documents","Maintain an injection corpus from public benchmarks plus your own red-team finds","Re-run the corpus in CI whenever prompts or tools change"],pitfalls:["Trusting PDFs or web pages as benign context","Human-in-the-loop rubber-stamping high-volume approvals"]}]}]},{id:"frontend-engineering",label:"Frontend Engineering",icon:"\uD83C\uDFA8",gradient:"from-pink-500 via-rose-500 to-orange-400",ring:"ring-pink-500/30",text:"text-pink-400",blurb:"Build fast, accessible, beautiful interfaces with React, Next.js, and modern CSS.",roles:["Frontend Engineers","Full-Stack Developers","Design Engineers","UI Developers"],domains:[{id:"react-patterns",label:"React Patterns",procedures:[{id:"server-client-boundary",title:"Draw the server/client component boundary",level:"intermediate",minutes:30,description:"Decide what renders on the server versus client in React Server Components to minimize JavaScript shipped.",tags:["react","nextjs","rsc"],steps:["Default every component to server-rendered; add interactivity at the leaves","Push 'use client' down to the smallest interactive subtree (buttons, inputs)","Fetch data in server components; pass plain serializable props downward","Never import server-only secrets from a client module, even indirectly","Keep providers minimal: theme/auth wrappers are client, pages stay server","Audit bundle after each feature: any client component over 15KB needs justification"],pitfalls:["One 'use client' at page level dragging the whole tree into the bundle","Passing functions or class instances across the boundary"],kpis:["Client JS per route under 120KB gzipped","Zero hydration mismatch warnings"]},{id:"state-collocation",title:"Colocate state where it is consumed",level:"foundation",minutes:25,description:"Choose between local state, lifted state, URL state, and stores by asking who needs the data and when.",tags:["state","architecture"],steps:["Start local with useState; lift only when a sibling truly needs it","Move shareable UI state (tab, sort, filters) into URL search params","Use a store only for cross-tree client state that changes often","Derive values during render instead of syncing via effects","Keep server data in a query cache, never copied into local state","Delete any effect whose dependency list keeps growing to mirror other state"],pitfalls:["Duplicating server data into useState then fighting staleness","Global store as default dumping ground"]},{id:"error-loading-states",title:"Design error, loading, and empty states first",level:"foundation",minutes:20,description:"Treat non-happy paths as features: skeleton loaders, typed errors, retry affordances, useful empties.",tags:["ux","resilience"],steps:["For every data section, spec loading, error, empty, and partial states upfront","Use skeletons matching final layout to avoid shift on load","Differentiate recoverable errors (retry button) from fatal ones (support link)","Write empty states as invitations: what this shows + how to populate it","Surface partial failures inline instead of failing the whole page","Add boundary components at route and widget level, logging with context"],pitfalls:["Infinite spinner hiding a thrown error","Empty tables with zero guidance"]}]},{id:"css-design-systems",label:"CSS & Design Systems",procedures:[{id:"design-tokens",title:"Set up design tokens for color, space, type",level:"intermediate",minutes:35,description:"Encode brand decisions as named tokens (CSS variables) consumed by utilities so themes change in one place.",tokens:!0,tags:["css","design-system","theming"],steps:["Define scales: one neutral ramp plus accent ramps, 8px spacing ladder, modular type scale","Name by role (bg-surface, text-muted), never by value (gray-3)","Expose as CSS variables; map Tailwind colors to var() references","Add dark mode by swapping variable values under a media or class hook","Lint for raw hex values outside the token file","Ship a living style page rendering every token with its name"],pitfalls:["Role names that encode light mode assumptions breaking dark theme","Token sprawl: 40 grays nobody can choose between"],variants:{tailwind:{id:"tailwind",label:"Tailwind setup",adds:["Reference variables in tailwind.config so utilities emit them","Use opacity modifiers carefully; they require rgb/hsl channel variables"]},vanilla:{id:"vanilla",label:"Vanilla CSS",adds:["Group tokens in @layer foundation so overrides stay predictable","Document contrast pairs (token-on-token) for accessibility"]}}},{id:"responsive-layout-system",title:"Build layouts that survive real content",level:"intermediate",minutes:30,description:"Use fluid grids, container queries, and content-driven breakpoints instead of pixel-perfect mockups.",tags:["css","layout","responsive"],steps:["Design mobile-first with min-width queries only","Prefer grid auto-fit + minmax over fixed column counts","Use clamp() for fluid type between readable bounds","Test with worst-case content: longest name, no image, RTL locale","Apply container queries for card-based components inside varying columns","Verify horizontal scrollbar never appears between 320px and 2560px"],pitfalls:["Breakpoints tuned to the designer's laptop width","Text truncation hiding critical numbers like prices"]},{id:"animation-craft",title:"Add motion that guides attention",level:"intermediate",minutes:30,description:"Animate with purpose: entrance choreography, micro-interactions, and reduced-motion respect.",tags:["css","animation","ux"],steps:["Define durations: 150ms feedback, 250ms transitions, 400ms entrances max","Animate transform and opacity only; layout properties cause jank","Choreograph staggered lists at 40-70ms increments","Give interactive elements hover AND active AND focus-visible motion","Wrap all animation in prefers-reduced-motion guards offering static fallbacks","Profile long pages; drop anything causing dropped frames mid-scroll"],pitfalls:["Entrance animations replaying on every tab return","Parallax that fights scroll-linked rendering on mobile"]}]},{id:"web-performance",label:"Web Performance",procedures:[{id:"core-web-vitals",title:"Fix Core Web Vitals regressions systematically",level:"advanced",minutes:45,description:"Diagnose LCP, INP, and CLS from field data and apply targeted fixes per metric rather than guessing.",tags:["performance","seo","vitals"],steps:["Pull field data (RUM) first; lab scores only reproduce what field data flags","For LCP: preload the hero asset, fix server TTFB, defer everything competing","For INP: break long tasks, debounce handlers, move work off main thread","For CLS: reserve dimensions for media, fonts, and late banners","Set per-template budgets in CI; fail builds on regression beyond 10%","Re-check after every third-party script change — they are the usual suspects"],pitfalls:["Optimizing lab LCP while field users on 3G suffer","A/B analytics snippets injected without async strategy"],kpis:["LCP p75 under 2.5s on 4G","CLS under 0.05 on top templates"]},{id:"image-pipeline",title:"Ship images that cost almost nothing",level:"foundation",minutes:25,description:"Modern formats, responsive sizes, lazy strategies, and priority hints for above-fold heroes.",tags:["images","performance"],steps:["Serve AVIF/WebP with automatic fallbacks via an image component or CDN","Generate responsive srcsets at 3-4 widths matched to actual layout slots","Lazy-load below-fold images; set fetchpriority=high on the LCP hero only","Always set explicit width and height to protect CLS","Strip metadata at upload; cap decoded size for thumbnails","Audit monthly for orphaned assets and unoptimized direct <img> usage"],pitfalls:["Lazy-loading the hero because a global wrapper applied it","Serving 2400px originals into 300px cards"]},{id:"js-bundle-diet",title:"Put JavaScript bundles on a diet",level:"intermediate",minutes:35,description:"Analyze, split, and replace dependencies so routes ship only the code they execute.",tags:["bundles","performance","dependencies"],steps:["Generate a bundle report; list the ten largest modules per route","Replace moment/lodash-class imports with native APIs or per-function imports","Dynamic-import heavy widgets (editors, charts) behind interaction","Move date/number formatting and markdown parsing server-side where possible","Set an import lint rule banning known-bloated packages","Track route-level JS budget over time; investigate any growth spike same week"],pitfalls:["Tree-shaking defeated by side-effectful barrel files","Polyfills duplicated by transpilation misconfig"]}]},{id:"accessibility",label:"Accessibility",procedures:[{id:"a11y-audit-pass",title:"Run a practical accessibility audit pass",level:"intermediate",minutes:40,description:"Combine automated scans with keyboard and screen-reader passes to find issues tools miss.",tags:["a11y","wcag","testing"],steps:["Automate first: axe scan on key routes, triage all criticals","Unplug the mouse: complete every core flow keyboard-only","Listen once with a screen reader through signup and checkout","Check focus visibility, order, and trap-free modals manually","Verify contrast against actual rendered colors including disabled states","File findings with WCAG criterion references and own fixes within sprint"],pitfalls:["Trusting automated score as proof of compliance","outline:none without a visible replacement"],kpis:["Zero critical axe issues","All flows completable keyboard-only"]},{id:"semantic-first-markup",title:"Write semantic markup before reaching for ARIA",level:"foundation",minutes:25,description:"Native elements carry behavior and semantics for free; ARIA is the fallback, not the default.",tags:["html","a11y"],steps:["Choose native elements: button not clickable-div, real headings in order","Use landmarks (nav, main, aside) so screen readers can jump regions","Label every input visibly; placeholder is not a label","Reserve ARIA for composite widgets you truly build custom","Test heading outline reads like the page's table of contents","Keep interactive targets 24px minimum with adequate spacing"],pitfalls:["aria-label duplicating visible text, read twice","Skip-links pointing to containers lacking tabindex"]}]}]},{id:"backend-engineering",label:"Backend Engineering",icon:"⚙️",gradient:"from-blue-500 via-cyan-500 to-teal-400",ring:"ring-blue-500/30",text:"text-blue-400",blurb:"APIs, databases, caching, queues, and auth that stay fast and correct under load.",roles:["Backend Engineers","API Developers","Platform Engineers","Full-Stack Developers"],domains:[{id:"api-design",label:"API Design",procedures:[{id:"rest-resource-modeling",title:"Model REST resources without leaking internals",level:"foundation",minutes:30,description:"Design stable resource-oriented endpoints with deliberate error contracts and pagination.",tags:["rest","api","http"],steps:["List nouns (resources) from the domain; map verbs to HTTP methods","Pluralize collections; nest at most one level for ownership","Standardize errors as {code, message, details} with correct status codes","Paginate every collection by cursor; never offset past 10k rows","Version in the URL path from v1; document deprecation policy","Publish an OpenAPI spec and generate clients from it"],pitfalls:["RPC-in-disguise endpoints like /getUserData","Leaking column names and internal IDs in payloads"],variants:{graphql:{id:"graphql",label:"GraphQL flavor",adds:["Schema-first types; expose one query root per aggregate","Enforce depth and complexity limits; disable introspection in prod if needed"]},rpc:{id:"rpc",label:"gRPC services",adds:["Define proto packages with backward-compatible field numbering","Map gRPC status codes to HTTP at the gateway"]}}},{id:"idempotency-keys",title:"Make writes safe with idempotency keys",level:"intermediate",minutes:30,description:"Accept retried mutations gracefully by keying operations so duplicates return the original result.",tags:["reliability","payments","api"],steps:["Require an Idempotency-Key header on POST payments, orders, and signups","Store key + request hash + response in a table with TTL cleanup","On replay with same payload, return stored response with replayed flag","On same key different payload, reject with 422 conflict","Expire keys after 24-48h depending on client retry windows","Load-test double-submit behavior before launch week"],pitfalls:["Keying only by user ID, colliding legitimate new requests","Storing responses forever without TTL or encryption"]},{id:"api-versioning-migration",title:"Migrate API versions without breaking clients",level:"advanced",minutes:40,description:"Run two versions in parallel, observe usage, and sunset safely with real telemetry.",tags:["versioning","migration"],steps:["Ship vN+1 alongside vN behind the same gateway; no big-bang cutover","Tag responses with version header so bug reports are attributable","Instrument per-client version adoption; email laggards with deadlines","Keep a contract test suite pinned per version in CI","Announce sunset twice: 90 days and 14 days before shutdown","Return 410 with migration guide URL after the date, not silent 404s"],pitfalls:["Silent breaking changes hidden inside 'minor' fixes","Sunsetting before the top-3 consumers migrate"]}]},{id:"databases",label:"Databases",procedures:[{id:"schema-design-basics",title:"Design schemas for change",level:"foundation",minutes:35,description:"Normalize enough to stay consistent, denormalize deliberately where reads demand it.",tags:["sql","schema","data-modeling"],steps:["Identify entities and relationships; write 10 queries you must answer well","Normalize to 3NF by default; document any intentional denormalization","Use UUIDs or bigint PKs; never emails or natural keys","Add created_at/updated_at with DB-level defaults on every table","Constrain with FKs, CHECKs, and NOT NULL — let the DB defend integrity","Review growth estimates: which table hits 100M rows first, plan partitioning now"],pitfalls:["Soft-delete columns complicating every unique constraint","Storing money as float instead of integer minor units"],variants:{postgres:{id:"postgres",label:"PostgreSQL",adds:["Prefer text with CHECK over varchar(n) unless limits are contractual","Use partial indexes for hot filtered subsets"]},mongo:{id:"mongodb",label:"MongoDB",adds:["Model around access patterns: embed what reads together","Validate with JSON Schema at the driver level"]},mysql:{id:"mysql",label:"MySQL",adds:["Pick InnoDB with utf8mb4; watch index length limits","Beware implicit type coercion in joins"]}}},{id:"query-optimization",title:"Optimize the slow queries actually hurting you",level:"intermediate",minutes:35,description:"Find top offenders from real traffic, read plans, add targeted indexes, verify improvements.",tags:["performance","sql","indexes"],steps:["Pull top-10 queries by total time from pg_stat_statements or slow log","Read EXPLAIN (ANALYZE) for each; find seq scans on growing tables","Index to match predicates AND sorts (composite order matters)","Cover hot read paths with covering indexes where sensible","Re-measure p95 after deploy; drop indexes that nobody uses","Guard CI against new seq-scan regressions on core tables"],pitfalls:["Indexing every column 'just in case', tanking write throughput","Functions wrapping indexed columns, silently disabling them"]},{id:"zero-downtime-migrations",title:"Run zero-downtime schema migrations",level:"advanced",minutes:40,description:"Expand-contract deployments so schema changes ship without locking tables or breaking running code.",tags:["migrations","deployments","sql"],steps:["Expand: add nullable columns/tables first; deploy code writing both paths","Backfill in batches with sleep/throttling; monitor replication lag","Switch reads to the new shape behind a flag; verify parity metrics","Contract: remove old columns only after N days of clean telemetry","Never rename or drop during peak; schedule low-traffic windows","Test every migration against a production-size snapshot first"],pitfalls:["CREATE INDEX without CONCURRENTLY blocking writes","Deploying code that assumes new column before migration runs"]}]},{id:"caching-queues",label:"Caching & Queues",procedures:[{id:"cache-strategy-layers",title:"Layer caching with explicit invalidation",level:"intermediate",minutes:35,description:"Decide what caches where (CDN, app, Redis) and how entries die so staleness stays bounded.",tags:["caching","redis","cdn"],steps:["Classify data: immutable (cache forever), mutable-TTL, never-cache (money)","Cache at CDN for anonymous GETs with stale-while-revalidate","Memoize expensive computed objects in-process with short TTL","Use Redis for shared cross-instance state; set TTLs on everything","Invalidate by key pattern on write events, not manual flushes","Monitor hit-rate per layer; below 60% means wrong layer or wrong keys"],pitfalls:["Caching authenticated responses at shared CDN edge","Thundering herd on expiry without jitter or locks"]},{id:"background-jobs",title:"Build trustworthy background job processing",level:"intermediate",minutes:35,description:"Queue async work with retries, dead-letters, and observability so failures surface instead of vanishing.",tags:["queues","async","reliability"],steps:["Make handlers idempotent; assume at-least-once delivery","Set exponential backoff with jitter; cap retries at sane counts","Dead-letter poison messages with full context for triage","Separate queues by latency class and priority; prevent head-of-line blocking","Emit metrics: depth, age of oldest job, success rate, duration percentiles","Alert on oldest-job-age, not just queue depth"],pitfalls:["Long jobs blocking a shared queue of quick tasks","Silent retries masking a permanently failing handler"]}]},{id:"auth-security",label:"Auth & Security Basics",procedures:[{id:"session-auth-hardening",title:"Harden session authentication",level:"intermediate",minutes:35,description:"Cookies, rotation, and revocation done right for server-rendered apps.",tags:["auth","sessions","cookies"],steps:["Store session ID in HttpOnly, Secure, SameSite=Lax cookies","Rotate session IDs on login and privilege change","Keep server-side session records enabling instant revocation","Expire idle sessions; re-authenticate before sensitive actions","Rate-limit login and reset endpoints per IP and per account","Log auth events to an append-only trail with device metadata"],pitfalls:["JWTs in localStorage inviting XSS token theft","No server-side revocation after 'logout everywhere' requests"]},{id:"input-validation-zod",title:"Validate all external input at the boundary",level:"foundation",minutes:25,description:"Parse, don't validate: coerce untrusted input into typed values once at the edge.",tags:["validation","security"],steps:["Define schemas per endpoint covering body, query, params, headers","Reject unknown fields by default; allowlists beat blocklists","Coerce types explicitly; fail closed on ambiguity","Return field-level errors machines can render","Reuse the same schemas for client-side forms where possible","Fuzz one nasty payload corpus against public endpoints in CI"],pitfalls:["Validating in UI but trusting raw req.body server-side","Mass assignment from spreads straight into ORM updates"]}]}]},{id:"data-engineering",label:"Data Engineering",icon:"\uD83D\uDEE2️",gradient:"from-cyan-500 via-teal-500 to-emerald-400",ring:"ring-cyan-500/30",text:"text-cyan-400",blurb:"Pipelines, warehouses, streaming, and data quality engineering that analysts can trust.",roles:["Data Engineers","Analytics Engineers","Platform Data Teams"],domains:[{id:"pipelines-batch",label:"Batch Pipelines",procedures:[{id:"pipeline-idempotency",title:"Make batch pipelines rerunnable by design",level:"intermediate",minutes:35,description:"Idempotent stages, partitioned writes, and backfill strategies so failures heal instead of corrupt.",tags:["etl","idempotency","orchestration"],steps:["Key every write by logical date/partition; overwrite partitions, never append blind","Design stages to be safely re-executable from any point of failure","Separate extraction, transformation, loading with checkpoints between","Backfill = same code, different parameter — prove it in staging first","Emit per-run metrics: rows in/out, duration, null-rates into a meta table","Alert on freshness SLA breach before stakeholders notice stale dashboards"],pitfalls:["append-only loads duplicating on retry","One giant DAG task failing everything for one bad record"]},{id:"schema-evolution-contracts",title:"Evolve schemas without breaking consumers",level:"advanced",minutes:40,description:"Schema contracts, compatibility modes, and deprecation flows across pipeline boundaries.",tags:["schema","contracts","governance"],steps:["Publish schema contracts per dataset with owner + compatibility mode (backward default)","CI-validate producer changes against registered contracts","Add columns nullable-first; never repurpose existing fields silently","Rename via add-new → dual-write → migrate → drop-old, with telemetry at each step","Notify consumer list (derived from query logs) before breaking changes","Archive old schema versions; make lineage queryable"],pitfalls:['"Temporary" column reuse changing meaning mid-history',"Producers shipping struct changes on Friday evenings"]},{slug:"data-quality-tests-warehouse",id:"dq-tests-warehouse",title:"Test warehouse data like software",level:"intermediate",minutes:30,description:"Freshness, uniqueness, referential, and business-invariant checks wired into orchestration.",tags:["data-quality","testing","warehouse"],variants:{snowflake:{id:"snowflake",label:"Snowflake",adds:["Leverage streams/tasks for change-driven tests","Watch warehouse credits: schedule heavy tests off-peak"]},bigquery:{id:"bigquery",label:"BigQuery",adds:["Use partition pruning in test queries to control scan costs","Assert on _TABLE_METADATA row counts cheaply"]},databricks:{id:"databricks",label:"Databricks/Delta",adds:["Use Delta EXPECTATIONS for inline quality gates","Track table properties for freshness metadata"]}},description:"Layered data quality tests that block bad data from reaching downstream consumers.",tags:["data-quality","testing"],steps:["Tier 0 volume/freshness: row counts within expected bands per partition","Tier 1 structural: uniqueness of keys, nullability, referential integrity","Tier 2 business invariants: revenue reconciles, statuses in enum sets","Fail loudly at tier matching blast radius; warn below it","Store test results historically to catch slow drift trends","Review false-positive rate monthly; noisy tests get ignored"],pitfalls:["Tests only in BI layer where nobody sees red","100% pass-rate suites proving nothing was tested"]}]},{id:"streaming-modeling",label:"Streaming & Modeling",procedures:[{id:"stream-processing-windows",title:"Choose windowing and watermarks correctly",level:"advanced",minutes:40,description:"Event-time vs processing-time decisions, late-data handling, and exactly-once semantics.",tags:["streaming","kafka","flink"],steps:["Timestamp on event time extracted from payload, not arrival","Set watermark delay from measured lateness distribution p99, not guesswork","Decide allowed-lateness policy: update vs side-output for stragglers","Key by cardinality you can hold state for; watch idle-key eviction","Verify exactly-once end-to-end through failure injection tests","Monitor watermark lag as the primary stream health metric"],pitfalls:["Processing-time windows rewriting history on replays","Unbounded state growth from high-cardinality keys"]},{id:"dimensional-modeling-refresh",title:"Apply dimensional modeling pragmatically",level:"intermediate",minutes:35,description:"Facts, dimensions, SCD strategy, and grain declarations serving analytics for years.",tags:["modeling","kimball","analytics"],steps:["Declare the grain of every fact table in its documentation header","Conform shared dimensions across facts before building marts","Pick SCD type deliberately: type-2 for history that matters, nothing else","Prefer wide tables for specific products over generic mega-marts","Add surrogate keys where natural keys churn","Model for the top 10 analyst questions; revisit quarterly"],pitfalls:["Mixed-grain fact tables producing wrong aggregates forever","Type-1 updates silently erasing history compliance needed"]}]}]},{id:"devops-cloud",label:"DevOps & Cloud",icon:"☁️",gradient:"from-sky-500 via-blue-500 to-indigo-500",ring:"ring-sky-500/30",text:"text-sky-400",blurb:"Containers, pipelines, infrastructure-as-code, observability, and calm incident response.",roles:["DevOps Engineers","SREs","Cloud Architects","Platform Engineers"],domains:[{id:"containers",label:"Containers",procedures:[{id:"dockerfile-production",title:"Write production-grade Dockerfiles",level:"intermediate",minutes:30,description:"Multi-stage builds, slim bases, layer-order discipline, and non-root runtime for small secure images.",tags:["docker","containers"],steps:["Start from slim/distroless variants pinned by digest, not :latest","Order layers least-to-most volatile; lock dependency manifests first","Multi-stage: build artifacts in builder, copy ONLY runtime needs","Run as non-root USER; expose no debug ports by default","Add HEALTHCHECK matching your orchestration's probe","Scan images in CI; fail on critical CVEs with a waiver process"],pitfalls:["Copying node_modules across stages including dev deps","apt-get upgrade layers busting cache every build"],kpis:["Image size under 200MB typical service","Zero critical CVEs shipped"]},{id:"compose-local-env",title:"Spin up reproducible local environments",level:"foundation",minutes:25,description:"One command brings up app plus dependencies with seeded data and sane defaults.",tags:["docker-compose","dx"],steps:["Compose file includes app, database, cache, queue with healthchecks","Mount code for live reload; keep volumes out of production paths","Seed scripts run automatically on first boot, idempotent after",".env.example documents every variable; fail fast on missing ones","Pin service versions; document the one-command README entry","Add make targets: up, down, logs, reset-db"],pitfalls:["Ports colliding with other projects; parameterize via env","Seed data drifting from production shapes"]}]},{id:"ci-cd",label:"CI/CD",procedures:[{id:"pipeline-stages",title:"Structure a fast, honest CI pipeline",level:"intermediate",minutes:35,description:"Stage ordering that fails cheap and fast: lint → unit → build → integration → deploy gates.",tags:["ci","github-actions","testing"],steps:["Fail cheapest first: format+lint under 2 minutes before anything heavy","Parallelize independent suites; cache dependencies by lockfile hash","Run builds with strict env mirroring production","Gate deploys on required checks only; no manual memory of 'it passed locally'","Upload artifacts (coverage, bundles) visible in PR checks","Keep total pipeline under 10 min p95; split flaky suites out for quarantine"],pitfalls:["Everything sequential behind one slow integration suite","Cache keys ignoring lockfiles causing phantom dependency bugs"],kpis:["p95 pipeline under 10 minutes","Flake rate below 1%"]},{id:"deploy-strategies",title:"Choose and execute deploy strategies",level:"advanced",minutes:35,description:"Rolling, blue-green, canary: pick per risk profile and wire automated rollback triggers.",tags:["deployment","rollbacks","canary"],steps:["Default to rolling with readiness gates for stateless services","Canary risky changes: 5% traffic, auto-halt on error-rate delta","Blue-green for schema-sensitive releases needing instant revert","Every deploy ships with a one-command rollback rehearsed quarterly","Verify post-deploy: synthetic checks plus error-budget burn alerting","Record release notes linking PRs for audit trails"],pitfalls:["Migrations entangled with app deploys violating expand-contract","Rollback tested for the first time during an incident"]}]},{id:"infrastructure-as-code",label:"Infrastructure as Code",procedures:[{id:"terraform-module-design",title:"Design Terraform modules people reuse",level:"intermediate",minutes:40,description:"Composable modules with typed variables, sensible defaults, and outputs that compose upward.",tags:["terraform","iac"],steps:["One module = one architectural decision (a network, a service, a store)","Type every variable; constrain with validation blocks","Defaults for 80% cases; no secret values as defaults ever","Outputs expose only what callers genuinely consume","Tag resources uniformly: env, owner, repo, cost-center","Version modules semver; changelog breaking moves loudly"],pitfalls:["Copy-pasted 800-line root modules nobody dares touch","count vs for_each migrations destroying remote state"]},{id:"state-management",title:"Manage IaC state safely as a team",level:"intermediate",minutes:30,description:"Remote state with locking, environment isolation, and least-privilege access so nobody corrupts prod.",tags:["terraform","state","collaboration"],steps:["Remote backends with locking enabled; never local state for shared infra"," Separate state per environment and blast-radius boundary","Plan applies through CI with reviewed plan artifacts","Restrict who can apply to prod; everyone can plan against staging copies","Backup state versions; rehearse recovery from zero","Import legacy resources deliberately with documentation"],pitfalls:["Shared state across envs turning staging apply into prod apply","-replace used casually against stateful resources"]}]},{id:"observability",label:"Observability",procedures:[{id:"golden-signals",title:"Instrument the four golden signals",level:"intermediate",minutes:35,description:"Latency, traffic, errors, saturation per service with SLO thresholds that map to user pain.",tags:["monitoring","metrics","slo"],steps:["Emit RED metrics per endpoint: rate, errors, duration histograms","Track saturation of the true bottleneck (connections, queue depth, CPU steal)","Define SLOs from user journeys, not server uptime vanity","Burn-rate alerts on fast+slow windows to catch real incidents early","Dashboards ordered by journey, not by org chart","Review signal usefulness quarterly; delete dashboards nobody opens"],pitfalls:["CPU alerts while users suffer on queue lag","Averages hiding p99 cliffs"]},{id:"structured-logging",title:"Adopt structured logging that answers questions",level:"foundation",minutes:25,description:"JSON logs with trace correlation and disciplined fields you can actually query at 3am.",tags:["logging","debugging"],steps:["Log JSON with timestamp, level, service, route, request_id, user_id","Propagate trace IDs across services and into log lines","Reserve ERROR for things needing action; INFO is default heartbeat","Never log secrets or PII; enforce with lint rules and sampling reviews","Sample high-volume debug logs; keep 100% of errors","Practice one query drill: 'find all errors for this user yesterday'"],pitfalls:["String-interpolated logs unsearchable in aggregators","Stack traces swallowed into single-line messages"]}]},{id:"incidents-vercel",label:"Incidents & Edge Deploys",procedures:[{id:"incident-response-flow",title:"Run a calm incident response flow",level:"intermediate",minutes:30,description:"Roles, comms cadence, and mitigation-first mindset that turns chaos into checklist.",tags:["incident-response","sre"],steps:["Declare early; assign Incident Commander separate from fixers","Mitigate first (rollback, feature-flag off), root-cause later","Post status updates every 30 min even when 'still investigating'","Log timeline entries with timestamps as decisions happen","End with customer-facing summary plus internal blameless retro within 48h","Convert every retro action item into tracked issues with owners"],pitfalls:["Hero debugging without comms, stakeholders blind","Retro actions dying in a doc"]},{id:"edge-deploy-workflow",title:"Ship frontends via edge platforms safely",level:"foundation",minutes:20,description:"Preview-per-PR, promotion flows, and env hygiene on platforms like Vercel/Netlify.",tags:["vercel","deployment","frontend"],steps:["Every PR gets a preview URL wired to ephemeral env vars","Protect prod: deploys gated on checks, promotions explicit not accidental","Keep secrets in platform env settings, never committed .env files","Alias domains to immutable deployments for instant rollback","Use tokens/CI for machine deploys; browser OAuth breaks on clock drift","Watch function limits: cold starts, memory, execution caps per plan tier"],pitfalls:["Team sharing one account instead of scoped tokens","Preview branches hitting production databases"]},{slug:"vercel-token-deploy",authored:!0,id:"token-deploy-cli",title:"Deploy to Vercel with token-based CLI auth",level:"intermediate",minutes:15,commands:[{label:"Link project",cmd:"vercel link --yes --project <name> --token $VERCEL_TOKEN"},{label:"Production deploy",cmd:"vercel deploy --prod --yes --token $VERCEL_TOKEN"}],description:"Authenticate Vercel CLI via a stored token instead of browser OAuth — the reliable path when clock drift breaks login flows. Use when deploying, linking projects, or scripting CI-style pushes.",tags:["vercel","cli","deployment"],steps:["Read the token from local storage at runtime into a shell variable only","Never echo, log, commit, or write the token into any file","Link once per project with vercel link --yes --project <name> --token $tok","Ship production with vercel deploy --prod --yes --token $tok","Prefer git push auto-deploys for repos already linked to GitHub integration","Scope team with --scope when the token spans multiple teams"],pitfalls:["Browser login loops caused by PC clock skew — use tokens exclusively","Tokens pasted into terminal history via inline export"]}]}]},{id:"engineering-essentials",label:"Engineering Essentials",icon:"\uD83E\uDDF0",gradient:"from-slate-400 via-zinc-400 to-stone-400",ring:"ring-zinc-500/30",text:"text-zinc-300",blurb:"Universal engineering craft — debugging, reviews, refactoring, profiling — tuned per language stack.",roles:["All Software Engineers"],domains:[{id:"debug-craft",label:"Debugging Craft",procedures:[{id:"systematic-bug-hunt",title:"Hunt bugs systematically",level:"foundation",minutes:30,description:"Reproduce, bisect, hypothesize, verify — the method that beats random poking under deadline pressure.",tags:["debugging","methodology"],steps:["Reproduce deterministically first; flaky repro = flaky fix","Write failing test capturing the bug before touching source","Bisect history or code path until minimal failing case remains","Form ONE hypothesis, predict its observable, then check","Fix root cause, not nearest symptom; add regression test","Document the hunt briefly for future searchers"],pitfalls:["Shotgun changes stacking unknown unknowns","Fixing symptoms while root cause ships elsewhere"],variants:s},{id:"production-debugging",title:"Debug production without stopping the world",level:"advanced",minutes:40,description:"Safe live diagnosis using flags, traces, and snapshots instead of restart roulette.",tags:["debugging","production","observability"],steps:["Correlate user report to trace IDs through gateway → service → data layer","Capture state non-invasively: heap/profile snapshots over process restarts","Enable dynamic log levels temporarily rather than redeploying","Test hypotheses against staging replicas of prod data shape","Timebox live debugging; mitigate via rollback/flag if past window","Write postmortem linking timeline to evidence artifacts"],pitfalls:["Restarting away evidence mid-diagnosis","Debugging against sanitized data missing the trigger shape"],variants:s}]},{id:"code-quality",label:"Code Quality",procedures:[{id:"code-review-checklist",title:"Review code like a senior engineer",level:"foundation",minutes:25,description:"Review order, comment quality, and scope discipline making PRs fast and kind.",tags:["code-review","quality","collaboration"],steps:["Read description and tests FIRST to learn intent","Check correctness and security before style nits","Comment questions/observations vs required-changes distinctly","Keep nitpicks batched as one optional pass","Approve explicitly when remaining items are optional","Aim same-day first response; latency kills momentum"],pitfalls:["Style wars the formatter should own","LGTM rubber-stamps on 2000-line diffs"],variants:s},{id:"refactor-safely",title:"Refactor without breaking behavior",level:"intermediate",minutes:35,description:"Characterization tests, small mechanical steps, and clean-cut commits keeping refactors boring.",tags:["refactoring","legacy-code"],steps:["Pin current behavior with characterization tests where gaps exist","Plan steps each leaving tests green; commit per step","Prefer mechanical moves (extract, inline, rename) over clever rewrites","Keep behavior changes in separate PRs from structure moves","Measure complexity delta honestly; stop when readability peaks","Leave the campsite cleaner but don't rebuild the forest"],pitfalls:["Big-bang rewrites losing hidden behaviors","'While I'm here' feature creep inside refactor PRs"],variants:s},{id:"performance-profiling",title:"Profile before optimizing",level:"intermediate",minutes:35,description:"Measure hot paths with real data shapes, optimize measured bottlenecks, verify wins.",tags:["performance","profiling"],steps:["Define target metric: p95 latency? memory ceiling? throughput?","Build benchmark using PRODUCTION-shaped data volumes","Profile CPU + memory + allocations; identify top three offenders","Optimize one offender at a time; re-measure after each change","Check second-order effects: cache misses, GC pressure, lock contention","Record before/after numbers in the PR for future archaeologists"],pitfalls:["Optimizing intuition while profile shows I/O waits","Micro-benchmarks on toy data lying about production"],variants:s}]},{id:"collab-workflow",label:"Collaboration Workflow",procedures:[{id:"git-discipline",title:"Practice git discipline teams thank you for",level:"foundation",minutes:25,description:"Commit hygiene, branch strategy, and recovery skills preventing shared-repo disasters.",tags:["git","workflow"],steps:["Atomic commits: one logical change, imperative message with why","Branch names carry ticket refs: feat/123-short-slug","Rebase local before PR; merge only via repo's chosen strategy","Master interactive rebase, reflog rescue, and bisect fluently","Never rewrite shared branches; force-push with lease only when agreed","Tag releases and keep changelog in sync mechanically"],pitfalls:["git push --force default aliasing over teammates","Thousand-line 'WIP' commits nobody can review"],variants:s},{id:"async-communication",title:"Communicate asynchronously like a distributed-native",level:"intermediate",minutes:20,description:"Written updates, decision records, and meeting hygiene across timezones.",tags:["communication","remote","writing"],steps:["Default to written updates with context links over synchronous asks","Structure messages: decision needed / FYI / blocked, upfront","Record decisions in ADRs searchable later, not chat scrolls","Set response-time expectations per channel explicitly","Meetings need agenda + owner + written outcome or get cancelled","Over-communicate status during incidents and crunch weeks"],pitfalls:["Decisions living only in someone's DMs","Meeting-recurrence zombie invites"]}]}]},{id:"cybersecurity",label:"Cybersecurity",icon:"\uD83D\uDD10",gradient:"from-red-500 via-orange-500 to-amber-400",ring:"ring-red-500/30",text:"text-red-400",blurb:"Application security, cloud hardening, and incident response that keep systems boring.",roles:["Security Engineers","AppSec","DevSecOps","Compliance Teams"],domains:[{id:"application-security",label:"Application Security",procedures:[{id:"threat-model-feature",title:"Threat model a feature before building it",level:"intermediate",minutes:40,description:"STRIDE-lite walkthrough producing mitigations wired into tickets before code exists.",tags:["threat-modeling","appsec"],steps:["Diagram the feature: actors, data flows, trust boundaries, stores","Walk STRIDE per boundary: spoofing, tampering, repudiation, info-disclosure, DoS, elevation","Rank findings by likelihood \xd7 impact; top items get design changes","Write mitigations as acceptance criteria in implementation tickets","Add abuse cases to the test plan alongside functional cases","Revisit the model when architecture shifts, not just annually"],pitfalls:["Threat models as one-time compliance theater","Trusting internal services implicitly across boundaries"]},{id:"secure-code-review",title:"Security-review code with a repeatable checklist",level:"intermediate",minutes:35,description:"Focused pass over authz, injection, secrets, and deserialization on risky diffs.",tags:["code-review","appsec","owasp"],steps:["Check authorization at object level: can user A read/write user B's records?","Trace all external input into queries/commands/paths for injection sinks","Scan diffs for hardcoded secrets; verify new config uses secret manager","Flag unsafe deserialization and eval-adjacent constructs","Verify security headers and CORS changes are intentional, not permissive defaults","Document accepted risks inline with ticket references"],pitfalls:["IDOR missed because tests only use one user","'Temporary' debug endpoints reaching production"]},{id:"secrets-hygiene",title:"Enforce secrets hygiene end to end",level:"foundation",minutes:25,description:"Generation, storage, rotation, and leak response for credentials humans inevitably touch.",tags:["secrets","keys","rotation"],steps:["Generate long random secrets via managers; ban hand-invented passwords","Inject at runtime from vault/KMS; forbid .env commits with real values","Pre-commit hooks scanning for high-entropy strings and known key formats","Rotate on schedule AND immediately after any suspected exposure","Scope every key least-privilege; prefer short-lived credentials","Practice the leak playbook: revoke → rotate → audit access → postmortem"],pitfalls:["Rotated old keys never actually revoked","Service accounts sharing one god-mode credential"]}]},{id:"cloud-hardening",label:"Cloud Hardening",procedures:[{id:"iam-least-privilege",title:"Right-size IAM to least privilege",level:"advanced",minutes:45,description:"Start scoped-down, expand only with evidence from real denied actions.",tags:["iam","cloud","zero-trust"],steps:["Inventory every identity: humans, services, CI roles, third parties","Replace wildcards with explicit actions gathered from access logs","Separate duties: deploy role cannot read databases","MFA enforced for console humans; no long-lived access keys","Set permission boundaries so escalation paths are capped","Quarterly access reviews with auto-expiring grants"],pitfalls:["Admin roles 'temporarily' granted during setup, forever","CI pipelines holding prod-write credentials"]},{id:"patch-cadence",title:"Run a patch cadence that actually closes windows",level:"intermediate",minutes:30,description:"Triage vulnerabilities by exploitability and ship patches within defined SLAs.",tags:["patching","vulnerability-management"],steps:["Aggregate findings from scanners, dependabots, and CISA feeds weekly","Classify by exploitability \xd7 exposure; internet-facing criticals patch in 72h","Automate dependency bumps with test-gated PRs","Maintain golden base images patched monthly","Track mean-time-to-patch per severity; report trend to leadership","Keep an exception register with expiries, not permanent waivers"],pitfalls:["Scanner noise drowning real risk; tune detections","Patching libraries while base images rot"]}]},{id:"incident-response-security",label:"Security Incident Response",procedures:[{id:"breach-first-hour",title:"Execute the first hour of a suspected breach",level:"advanced",minutes:30,description:"Contain, preserve evidence, and communicate without tipping off or destroying forensics.",tags:["incident-response","forensics"],steps:["Activate the IR channel; start a timestamped scribe log immediately","Preserve evidence BEFORE aggressive remediation (snapshots, memory dumps)","Contain: revoke sessions/keys, isolate affected hosts, block indicators","Determine blast radius: what data, which accounts, what timeframe","Engage legal/compliance early for notification obligations (e.g., 72h GDPR)","Brief executives with facts-not-speculation updates hourly"],pitfalls:["Wiping compromised machines destroying evidence","Silent handling violating breach-notification laws"],variants:{ransomware:{id:"ransomware",label:"Ransomware scenario",adds:["Isolate backups and verify offline copies intact before any recovery","Never negotiate or pay without legal + law-enforcement consultation"]}}},{id:"phishing-defense-program",title:"Stand up phishing defense beyond training videos",level:"intermediate",minutes:30,description:"Technical controls + easy reporting + blameless drills reducing real click-through damage.",tags:["phishing","social-engineering","awareness"],steps:["Enforce MFA everywhere, preferring phishing-resistant methods (FIDO2)","Deploy DMARC with enforcement; monitor failing sources","One-click report button feeding a monitored mailbox","Simulate quarterly; measure report-rate not just click-rate","Auto-quarantine messages matching reported patterns","Blameless follow-ups: fix the process that made the lure plausible"],pitfalls:["Shaming clickers, teaching people to hide clicks","SMS OTP treated as phishing-resistant"]}]}]},{id:"cyber-defense-ops",label:"Cyber Defense & SOC",icon:"\uD83D\uDEE1️",gradient:"from-red-700 via-rose-600 to-orange-500",ring:"ring-red-500/30",text:"text-red-400",blurb:"Security operations: alert triage, threat hunting, detection engineering, and purple-team rigor.",roles:["SOC Analysts","Detection Engineers","Threat Hunters","Blue Teams"],domains:[{id:"soc-operations",label:"SOC Operations",procedures:[{id:"alert-triage-discipline",title:"Triage alerts with consistent depth",level:"foundation",minutes:25,description:"Enrichment order, true/false-positive calls with evidence, and escalation criteria applied identically every shift.",tags:["triage","soc","enrichment"],steps:["Pull alert context first: entity history, related alerts last 7 days","Enrich systematically: IP reputation, hash verdicts, identity risk, asset criticality","Validate against known-change calendar before calling malicious","Classify with evidence links attached — no verdict without artifact","Escalate by blast radius criteria written down, not gut feel","Log analyst notes reusable by the next person"],pitfalls:["Auto-closing batches to clear the queue before events","Verdicts without captured evidence being unreproducible"]},{id:"hunt-hypothesis",title:"Hunt threats with falsifiable hypotheses",level:"advanced",minutes:45,description:"Structured hunts starting from TTP intelligence, producing detections or documented negatives.",tags:["threat-hunting","mitre","proactivity"],steps:["Pick one TTP from intel relevant to your stack this month","Write hypothesis: 'IF technique X used THEN artifacts Y visible in Z source'","Verify telemetry actually covers Z before hunting (coverage map)","Query broadly first, narrow on anomaly clusters","Outcome A: findings → immediate detection rule + IR handoff","Outcome B: negative → document coverage gap or baseline noise profile"],pitfalls:["Hunting where logs don't exist, wasting hours","Findings living in hunt notes, never becoming detections"]},{id:"log-source-coverage",title:"Map log source coverage to attack surface",level:"intermediate",minutes:35,description:"Inventory what you can see versus what attacks require, closing blind spots deliberately.",tags:["visibility","logging","coverage"],steps:["List top MITRE techniques relevant to your industry threat profile","Map each to required telemetry source and current ingestion status","Score coverage: full / partial / none per technique","Prioritize gaps by likelihood \xd7 detection-value","Fund onboarding of highest-value sources with success tests","Re-map quarterly; infrastructure drifts silently"],pitfalls:["Ingesting everything equally, cost exploding value flat","Coverage assumed rather than tested with synthetic events"]}]},{id:"detection-purple",label:"Detection & Purple Team",procedures:[{id:"detection-rule-lifecycle",title:"Engineer detections through a full lifecycle",level:"advanced",minutes:40,description:"Rule ideation, tuning against baselines, staged rollout, and measured precision over time.",tags:["detection-engineering","sigma","siem"],variants:{splunk:{id:"splunk",label:"Splunk",adds:["Version rules in a git-backed ES correlation search repo","Use data models to keep searches acceleration-friendly"]},sentinel:{id:"sentinel",label:"Microsoft Sentinel",adds:["Deploy analytics rules as code via ARM/Bicep pipelines","Watch ingestion latency when setting query frequency"]}},description:"Ship detection rules like code: versioned, tested, tuned, and retired deliberately.",tags:["detection-engineering","as-code"],steps:["Draft rule from hunt/intel with explicit logic rationale documented","Backtest against 30 days of data; measure raw hit volume","Tune out benign-true noise using environment baselines, not blanket exclusions","Stage: silent-run in prod for one week comparing predicted vs actual hits","Enable with severity matched to expected fidelity; document false-positive budget","Review rule precision quarterly; retire or rewrite below threshold"],pitfalls:["Rules enabled then never revisited until they page falsely","Exclusions so broad they hollow out the logic"]},{id:"purple-validation",title:"Validate detections with purple-team exercises",level:"intermediate",minutes:40,description:"Safe technique emulation proving alerts fire end-to-end, producing concrete coverage evidence.",tags:["purple-team","validation","atomic"],steps:["Select atomic tests matching your mapped priority techniques","Run in isolated lab mirroring production logging config exactly","Trace: did endpoint event reach SIEM parse correctly AND alert fire?","Record three states: detected / ingested-not-alerted / not-ingested","File engineering tickets per gap with retest dates","Report coverage trend to leadership in techniques-validated terms"],pitfalls:["Testing in labs whose log pipelines differ from production","Emulations risky enough to trigger real incidents uncontrolled"]},{id:"tabletop-facilitation",title:"Facilitate ransomware tabletops that find truth",level:"intermediate",minutes:40,description:"Scenario injects probing decision boundaries, revealing plan gaps without blame theater.",tags:["tabletop","incident-response","exercises"],steps:["Pick scenario targeting THIS org's crown jewels, not generic templates","Script escalating injects with decision points and time pressure","Assign roles including uncomfortable ones (legal, comms, CEO availability)","Capture decision log verbatim; gaps speak louder than slides","Debrief into ranked remediations with owners and deadlines","Retest failed injects in the next exercise cycle"],pitfalls:["Scenarios so fictional everyone plays along harmlessly","Action items dying between exercises year after year"]}]}]},{id:"data-science",label:"Data Science & Analytics",icon:"\uD83D\uDCCA",gradient:"from-emerald-500 via-green-500 to-teal-400",ring:"ring-emerald-500/30",text:"text-emerald-400",blurb:"Exploration, statistics, experimentation, and visualization that turn data into decisions.",roles:["Data Scientists","Analysts","Research Scientists","Product Analysts"],domains:[{id:"exploratory-analysis",label:"Exploratory Analysis",procedures:[{id:"dataset-health-check",title:"Run a dataset health check before modeling",level:"foundation",minutes:30,description:"Profile distributions, missingness, leakage risks, and unit sanity before trusting any result.",tags:["eda","data-quality"],units:!0,steps:["Check shape, dtypes, and unique counts; flag columns failing expectations","Plot distributions for numeric columns; eyeball impossible values","Quantify missingness patterns: MCAR vs structured gaps telling stories","Hunt leakage: fields created after outcome timestamps","Verify joins didn't fan-out rows silently (count before/after)","Write a one-page data dictionary others can trust"],pitfalls:["Aggregating across mixed currencies/timezones","Imputing before understanding why data is missing"]},{id:"correlation-causation",title:"Avoid correlation traps in stakeholder analyses",level:"intermediate",minutes:25,description:"Stress-test relationships with confounder thinking and simple falsification checks.",tags:["statistics","causal-inference"],steps:["Ask what could drive both variables; list top three confounders","Stratify or control for obvious confounders and see if effect survives","Run falsification tests: effect should vanish under placebo splits","Frame findings as associations unless design supports causality","Pre-register hypotheses for decisions that matter","Communicate uncertainty ranges, never naked point estimates"],pitfalls:["Simpson's paradox flipping conclusions after segmentation","Post-hoc story fitting presented as discovery"]},{id:"cohort-funnel-analysis",title:"Build cohort and funnel analyses that hold up",level:"intermediate",minutes:35,description:"Segment users by acquisition period and trace retention/funnels without sampling traps.",tags:["analytics","retention","product"],steps:["Define cohorts by first meaningful action, not signup alone","Choose observation windows honestly; censor incomplete periods","Normalize funnels per-entry so step conversion is comparable","Segment by platform before concluding; mixed traffic misleads","Visualize retention curves with cohort overlay to spot shifts","Annotate charts with launches/incidents explaining inflections"],pitfalls:["Comparing cohorts with unequal maturity windows","Counting bots as activated users"]}]},{id:"experimentation",label:"Experimentation & A/B Testing",procedures:[{id:"ab-test-design",title:"Design an A/B test you can trust",level:"intermediate",minutes:35,description:"Power the test upfront, guard metrics, and commit to decision rules before peeking.",tags:["ab-testing","statistics","product"],steps:["Define one primary metric with minimum detectable effect from business value","Compute required sample size for 80% power at α=0.05 two-sided","Randomize at user level with sticky assignment across sessions","Add guardrail metrics: latency, error rate, unsubscribe, revenue per user","Commit to runtime and decision rule BEFORE launch; no mid-flight goalposts","Log the design doc; results include confidence intervals not just p-values"],pitfalls:["Peeking daily and stopping at first significance","Underpowered tests 'proving' null effects"],kpis:["100% of launched tests with pre-registered designs","SRM check passing (sample ratio mismatch)"]},{id:"metric-definition-contracts",title:"Write metric definitions as contracts",level:"intermediate",minutes:30,description:"One canonical definition per metric, versioned and documented, killing dashboard wars.",tags:["metrics","governance","analytics-engineering"],steps:["Create a metric catalog entry per KPI: formula, grain, filters, owner","Specify inclusion/exclusion rules explicitly (bots, refunds, internal staff)","Implement once in the semantic layer; dashboards reference it","Version definitions; changelog when business logic changes","Backfill check: recompute last 12 months after any change","Review catalog quarterly; archive dead metrics loudly"],pitfalls:["'Active users' meaning three things in three dashboards","Revenue defined differently between finance and product"]}]},{id:"ml-modeling",label:"Modeling Practice",procedures:[{id:"baseline-first-modeling",title:"Baseline before you boost",level:"foundation",minutes:25,description:"Ship trivial baselines (mean, logistic, linear) to price complexity honestly.",tags:["ml","modeling","baselines"],steps:["Predict the prior/majority class; record its metric as floor","Fit one linear/logistic model with sane regularization","Add one gradient-boosted model only if it beats baseline materially","Compare on identical splits and preprocessing pipelines","Quantify lift in business terms, not just AUC deltas","Deploy the simplest model within epsilon of the best"],pitfalls:["Deep nets on tabular data losing to logistic regression","Metrics improving while business outcomes don't"]},{id:"leakage-prevention",title:"Prevent data leakage in ML pipelines",level:"advanced",minutes:35,description:"Split-aware preprocessing, temporal boundaries, and feature provenance keeping offline gains real online.",tags:["ml","validation","leakage"],steps:["Split temporally when production predicts the future","Fit scalers/imputers/encoders inside folds only, never full data","Ban features unavailable at prediction timestamp (audit with data team)","Group correlated rows (same user/device) into same split side","Track feature computation code versions with model artifacts","Validate: offline-vs-online correlation checked each release"],pitfalls:["Random shuffles leaking user histories across train/test","Target encoding fit on full dataset"]}]}]},{id:"ml-research",label:"ML Research Engineering",icon:"\uD83E\uDDEE",gradient:"from-blue-500 via-cyan-400 to-teal-300",ring:"ring-blue-500/30",text:"text-blue-400",blurb:"Rigorous ML experimentation: reproductions, ablations, tracking, and honest benchmarking.",roles:["Research Engineers","ML Scientists","PhD Researchers","Applied Scientists"],domains:[{id:"experimentation-rigor",label:"Experimentation Rigor",procedures:[{id:"paper-reproduction-protocol",title:"Reproduce papers without drowning",level:"advanced",minutes:50,description:"Staged reproduction from inference-first to full retrain with deviation journals.",tags:["reproduction","papers","methodology"],steps:["Stage 0: run authors' code if available; record environment verbatim","Stage 1: reimplement inference on their checkpoint; compare outputs numerically","Stage 2: retrain smallest configuration matching reported metrics \xb1noise band","Journal EVERY deviation from paper text with suspected impact","Contact authors once with specific questions — response rate rewards clarity","Publish reproduction report regardless of outcome; negatives are valuable"],pitfalls:["Jumping straight to full-scale retraining","Undocumented 'small' tweaks compounding into irreproducibility"]},{id:"ablation-design",title:"Design ablations that isolate contributions",level:"intermediate",minutes:35,description:"One-factor-at-a-time with matched budgets separating real gains from tuning luck.",tags:["ablations","experimental-design"],steps:["List claimed components; rank by novelty and implementation cost","Baseline run repeated with 3+ seeds establishing variance floor","Remove ONE component per run; keep all else byte-identical","Match compute budgets across arms — bigger ablation runs cheat","Report deltas WITH seed variance, not single-run point estimates","Test interactions for top-2 components before final claims"],pitfalls:["Ablations run with different hyperparameter sweeps","Seed cherry-picking turning noise into conclusions"]},{id:"experiment-tracking-hygiene",title:"Keep experiment tracking trustworthy",level:"foundation",minutes:30,description:"Every run reproducible from logged config + code version + data snapshot reference.",tags:["tracking","mlops","reproducibility"],steps:["Log config automatically from source of truth, never hand-transcribed","Attach git SHA + diff for uncommitted changes to every run","Reference datasets by content hash or immutable version tag","Name runs by hypothesis ID, not creative adjectives","Tag runs: baseline / candidate / aborted / champion with promotion reasons","Weekly review: kill zombie experiments, archive stale branches"],pitfalls:["Best result ever that nobody can rerun","Config drift between what ran and what was documented"]}]},{id:"evaluation-integrity",label:"Evaluation Integrity",procedures:[{id:"benchmark-selection-honesty",title:"Choose benchmarks that mean something",level:"intermediate",minutes:30,description:"Benchmark suites matched to target capabilities with contamination checks and honest scopes.",tags:["benchmarks","evaluation","integrity"],steps:["Define capability claims first; benchmarks follow claims, not reverse","Check train/test contamination against your corpora before trusting numbers","Prefer held-out private sets for anything heading to publication","Report full suite including unfavorable tasks, not highlights","State statistical significance; differences inside noise bands are ties","Archive exact eval configs alongside results permanently"],pitfalls:["SOTA claimed on benchmarks the model effectively memorized","Task suites drifting between model generations"]},{id:"datasheet-documentation",title:"Document datasets with datasheets",level:"foundation",minutes:30,description:"Provenance, composition, collection process, and limitations recorded before modeling begins.",tags:["datasets","documentation","responsible-ai"],steps:["Record provenance chain: sources, licenses, consent basis for personal data","Quantify composition: demographics/classes/languages with known skews stated","Document collection mechanics and any filtering applied","List known failure modes and unsuitable-use cases explicitly","Version datasheets with dataset versions — they evolve together","Review for PII leakage risks with fresh eyes before release"],pitfalls:["Datasets inherited without provenance entering production models","Limitations sections written only when reviewers ask"]}]}]},{id:"product-management",label:"Product Management",icon:"\uD83D\uDCCB",gradient:"from-amber-500 via-yellow-500 to-lime-400",ring:"ring-amber-500/30",text:"text-amber-400",blurb:"Discovery, prioritization, specs, and launch craft that turn insight into shipped value.",roles:["Product Managers","Product Owners","Founders","Product Analysts"],domains:[{id:"discovery",label:"Discovery & Research",procedures:[{id:"customer-interviews",title:"Interview customers without leading them",level:"foundation",minutes:30,description:"Past-behavior questions, silence discipline, and synthesis habits that surface real problems.",tags:["discovery","user-research","interviews"],steps:["Recruit for recent relevant experience ('last time you…'), not demographics","Ask about past behavior and specific episodes; avoid hypotheticals","Follow the 'why' chain five deep past stated solutions","Embrace silence after answers; people fill it with truth","Take verbatim quotes; paraphrase kills signal","Synthesize within 24h: patterns, surprises, verbatims, next questions"],pitfalls:["Pitching your idea mid-interview for validation","Ten interviews all confirming the loudest customer"]},{id:"opportunity-sizing",title:"Size opportunities honestly",level:"intermediate",minutes:30,description:"Bottom-up TAM math with explicit assumptions anyone can audit.",tags:["strategy","market-sizing"],steps:["Build bottom-up: segments \xd7 reach rate \xd7 conversion \xd7 price","List every assumption with source and confidence rating","Cross-check with one independent method (top-down or value-based)","Present ranges with sensitivity on the two shakiest assumptions","Separate 'market exists' from 'we can reach them' explicitly","Date-stamp the analysis; markets move"],pitfalls:["1% of China logic presented as sizing","Confusing total market with reachable segment"]}]},{id:"prioritization-roadmap",label:"Prioritization & Roadmaps",procedures:[{id:"roadmap-outcomes",title:"Build outcome-based roadmaps",level:"intermediate",minutes:35,description:"Communicate problems and metrics per quarter, leaving solution space for teams.",tags:["roadmap","strategy","okrs"],steps:["Structure by quarter → outcome metric → problem statements, not feature lists","Attach each bet to a company-level objective explicitly","Mark confidence: now/next/later with evidence tags","Reserve ~20% capacity for unplanned learning and debt","Review monthly against leading indicators; kill zombie bets","Share externally-safe version with customers to reset expectations"],pitfalls:["Gantt charts of features pretending certainty","Roadmap as promise archive nobody revisits"]},{id:"prioritization-framework-fit",title:"Choose a prioritization framework that fits your stage",level:"foundation",minutes:25,description:"RICE vs cost-of-delay vs simple-now-list: pick per team maturity and decision cadence.",tags:["prioritization","frameworks"],steps:["Inventory current backlog candidates with owners attached","Early stage: rank by founder judgment + one metric; speed beats ceremony","Scale stage: RICE with calibrated effort from eng estimates","Platform investments: cost-of-delay thinking over point scores","Cap WIP explicitly; priorities without capacity are fiction","Recalibrate scores quarterly against realized outcomes"],pitfalls:["Precision theater: scores to three decimals on guesses","Framework outputs ignored when HiPPO speaks"]}]},{id:"specs-launch",label:"Specs & Launch",procedures:[{id:"prd-one-page",title:"Write a one-page PRD engineers love",level:"foundation",minutes:40,description:"Problem, users, success metrics, scope fences, and open questions on one page.",tags:["prd","writing","spec"],steps:["Lead with problem statement and target user's current workaround","Define success metrics with baseline numbers and targets","List in-scope v1 and explicitly out-of-scope items","Specify edge cases and non-functional requirements (perf, a11y, privacy)","Keep an open-questions section with owners and due dates","Review with engineering before finalizing; incorporate feasibility push-back"],pitfalls:["Solution mockups posing as requirements","Success metrics undefined until post-launch retro"]},{id:"launch-checklist",title:"Run launches with a go/no-go checklist",level:"intermediate",minutes:30,description:"Coordinated release across support, marketing, legal, and engineering with rollback plans.",tags:["launch","go-to-market","coordination"],steps:["Freeze scope two weeks out; bug-fix-only policy","Verify analytics events fire correctly in staging AND preview","Support briefed with FAQ, known issues, escalation path","Legal/privacy sign-off for anything touching personal data","Rollback plan rehearsed: flags off or previous version restore","Schedule T+1 and T+7 metric reviews before celebrating"],pitfalls:["Analytics broken on day one making results unreadable","Support discovering features from user tickets"]}]}]},{id:"ux-research",label:"UX Research & Design",icon:"\uD83E\uDDE0",gradient:"from-sky-400 via-cyan-400 to-teal-300",ring:"ring-sky-500/30",text:"text-sky-400",blurb:"Usability studies, research synthesis, design systems thinking, and evidence-driven product design.",roles:["UX Researchers","Product Designers","Design Leads","Service Designers"],domains:[{id:"research-methods",label:"Research Methods",procedures:[{id:"usability-test-script",title:"Run usability tests that reveal truth",level:"foundation",minutes:35,description:"Task-based sessions with neutral scripting, think-aloud discipline, and severity-rated findings.",tags:["usability-testing","user-research"],steps:["Write tasks as goals ('pay this invoice'), never UI instructions ('click Billing')","Pilot the script on a colleague; fix leading phrases","Remind participants their failures are findings, not mistakes","Probe silence: 'what are you thinking?' beats helping","Rate issues post-session: severity \xd7 frequency, quotes attached","Deliver top-5 ranked fixes within 48h while fresh"],pitfalls:["Demonstrating the flow 'just to save time' contaminating results","Testing with teammates who know the product"]},{id:"survey-instrument-quality",title:"Write surveys without garbage-in",level:"intermediate",minutes:30,description:"Question construction, ordering effects, and response-scale discipline producing analyzable data.",tags:["surveys","quantitative-research"],steps:["Draft research questions first; every item maps to one","One idea per question; kill double-barrels ruthlessly","Balanced scales with labeled midpoints; avoid agree-only sets","Randomize option order where position bias lurks","Add one attention-check and one open-ended for voice","Pilot n=10, inspect distributions and timing before full send"],pitfalls:["Leading questions collecting confirmation, not data","Ten-point scales nobody can meaningfully differentiate"]},{id:"synthesis-affinity",title:"Synthesize research without bias collapse",level:"advanced",minutes:40,description:"Affinity mapping with evidence tagging separating observation from interpretation.",tags:["synthesis","analysis","workshop"],steps:["Extract observations verbatim onto atomic notes with source refs","Cluster by pattern, NOT by person or session order","Name clusters descriptively before interpretively","Tag insight strength: single-source vs multi-user convergence","Separate insights from recommendations explicitly","Store the map; future decisions cite evidence lineage"],pitfalls:["Loudest stakeholder's pet theory shaping clusters","Insights so general they justify any decision"]}]},{id:"design-practice",label:"Design Practice",procedures:[{id:"design-review-run",title:"Run design reviews that improve work",level:"intermediate",minutes:25,description:"Structured critique rituals: intent first, questions before solutions, owner decides.",tags:["critique","collaboration","design-process"],steps:["Designer opens with context, constraint, and specific feedback asks","Reviewers describe observed effects before proposing changes","Questions outnumber statements; 'what if' over 'you should'","Timebox per artifact; park tangents visibly","Owner records decisions and explicitly defers or accepts each thread","Follow up next review on prior feedback resolution"],pitfalls:["HiPPO redesigns announced as feedback","Reviews becoming taste debates without user grounding"]},{id:"journey-mapping-service",title:"Map journeys across service touchpoints",level:"intermediate",minutes:40,description:"Current-state journey maps exposing emotional lows and operational handoff failures.",tags:["journey-mapping","service-design"],steps:["Pick ONE persona + scenario with real data behind it","Lay stages by user language, not internal process names","Per stage: actions, thoughts, emotions curve, backend actors","Mark handoffs between teams — pain concentrates there","Quantify lows with support tickets/interviews evidence","Prioritize fixes at emotion valleys \xd7 business impact"],pitfalls:["Idealized future-state maps pretending current pain away","Maps as wall art never revisited"]}]}]},{id:"engineering-leadership",label:"Engineering Leadership",icon:"\uD83E\uDDED",gradient:"from-indigo-500 via-violet-500 to-purple-500",ring:"ring-indigo-500/30",text:"text-indigo-400",blurb:"Managing engineers, running teams, hiring, planning, and open-source stewardship.",roles:["Engineering Managers","Tech Leads","Staff Engineers","CTOs"],domains:[{id:"people-management",label:"People Management",procedures:[{id:"one-on-ones",title:"Run one-on-ones that build trust",level:"foundation",minutes:25,description:"Weekly direct-report meetings owned by them: growth, blockers, feedback — not status updates.",tags:["management","1on1","feedback"],steps:["Their agenda first; status belongs in tools not this meeting","Ask growth questions monthly: what do you want to learn next quarter?","Deliver small feedback within 48h of observation, privately","Track recurring themes across weeks; patterns need structural fixes","Skip-meeting check: if nothing to discuss, cancel honestly","Quarterly: review their goals explicitly in the slot"],pitfalls:["1:1s degraded into sprint demos","Feedback saved for performance season"]},{id:"performance-calibration",title:"Calibrate performance reviews fairly",level:"advanced",minutes:45,description:"Evidence-based reviews with bias checks and consistent leveling across teams.",tags:["performance","reviews","fairness"],steps:["Collect evidence continuously, not from last-month memory","Score against written level expectations, not peer comparison","Check for bias patterns: recency, likability, visibility of work","Calibrate across managers with anonymized examples","Separate compensation conversations from growth conversations","No surprises rule: anything in the review was said when observed"],pitfalls:["Rockstar-effect inflating visible work over critical invisible work","Reviews as annual surprise attack"]}]},{id:"team-process",label:"Team Process",procedures:[{id:"sprint-ceremonies-audit",title:"Audit your agile ceremonies ruthlessly",level:"intermediate",minutes:30,description:"Keep rituals that produce decisions; delete the rest or shorten them.",tags:["agile","process","meetings"],steps:["Timebox audit: cost each ceremony \xd7 attendees \xd7 frequency annually","Standups answer three things only: done, next, blocked","Planning consumes estimates only where they change decisions","Retro produces max two tracked actions with owners","Async-first updates replace broadcast meetings","Re-audit quarterly; ceremony creep is real"],pitfalls:["Ceremonies performed for process-compliance optics","Estimation debates longer than implementation"]},{id:"tech-debt-strategy",title:"Manage tech debt as a portfolio",level:"advanced",minutes:35,description:"Classify debt by interest rate, allocate fixed capacity, and tie paydown to business risk.",tags:["tech-debt","strategy","maintenance"],steps:["Inventory debts with interest rate: how much slower/costlier per month?","Tag principal risk: what breaks if this component fails?","Allocate 15-20% sprint capacity permanently, protected","Bundle paydown with adjacent feature work where paths cross","Kill dead code aggressively; deletion is the cheapest fix","Report debt burn-down alongside features to leadership"],pitfalls:["Debt weeks that become bug-fix weeks","Rewrite fantasies instead of incremental strangling"]}]},{id:"hiring",label:"Hiring",procedures:[{id:"structured-interviews",title:"Run structured interviews with scorecards",level:"intermediate",minutes:40,description:"Same questions, rubric scoring, independent write-ups before debrief — predictive and fair.",tags:["hiring","interviewing","talent"],steps:["Derive 4-5 competencies from actual job outcomes","Write question sets per competency with follow-up probes","Score on behavioral anchors (1-5 descriptions) immediately after","Interviewers submit written scores before any group discussion","Debrief discusses evidence against competencies only","Audit funnel quarterly for stage-level drop-off biases"],pitfalls:["Brainteasers measuring trivia tolerance","Group-think debriefs anchored by loudest voice"]},{id:"candidate-experience",title:"Design a candidate experience worth talking about",level:"intermediate",minutes:25,description:"Fast loops, real communication, respect for time — your employer brand compounds here.",tags:["hiring","employer-brand"],steps:["Publish salary range and process map in the job post","Total loop under 3 weeks; feedback within 2 days every stage","Take-home capped at 3 hours or paid work-sample alternative","Every rejection includes one specific kind sentence","Onboarding starts at offer-accept: day-one access checklist","Survey candidates post-loop; act on top complaint"],pitfalls:["Ghosting after final rounds nuking Glassdoor scores","Five interviewers asking the same resume questions"]}]},{id:"open-source-stewardship",label:"Open Source Stewardship",procedures:[{id:"maintainer-triage",title:"Triage issues like a sustainable maintainer",level:"intermediate",minutes:30,description:"Labels, templates, and response SLAs keeping the queue trustworthy without burnout.",tags:["open-source","triage","community"],steps:["Install issue templates forcing repro steps and versions","Label within 48h: type, area, priority, good-first-issue","Close unreproducible issues politely with a checklist ask","Pin a contributing guide with PR conventions and CLA status","Batch triage twice weekly; notifications are not a workflow","Recruit trusted contributors toward triage permissions"],pitfalls:["Maintainer as single point of failure for every decision","Issue queue growing unbounded until contributors leave"]},{slug:"oss-pr-landing",authored:!0,id:"pr-landing-playbook",title:"Land merged PRs in large OSS repositories",level:"intermediate",minutes:30,description:"A merge-rate-first contribution workflow: issue selection, minimal diffs, review follow-through. Use when contributing to someone else's repo, opening PRs upstream, or reviving stalled pull requests.",tags:["open-source","pull-requests","contribution"],commands:[{label:"Find good first issues",cmd:'gh search issues --repo <owner>/<repo> "good first issue" --state open'}],steps:["Pick labeled issues with recent maintainer activity; claim in a comment","Read CONTRIBUTING.md, AGENTS.md, and ten recent merged commits first","Branch per issue; one logical change per PR","Include tests matching repo conventions; keep diff reviewable in one sitting","Open with Fixes #n, proof of behavior before/after, test output","Answer every review comment same-day; ping politely once after two silent weeks"],pitfalls:["Unrequested feature PRs to roadmap items","Drive-by reformatting bloating diffs"]}]}]},{id:"people-hr",label:"People & HR",icon:"\uD83D\uDC65",gradient:"from-rose-500 via-pink-500 to-fuchsia-500",ring:"ring-rose-500/30",text:"text-rose-400",blurb:"Recruiting, onboarding, policies, and people operations that scale with empathy.",roles:["HR Managers","Recruiters","People Ops","Team Leads"],domains:[{id:"recruiting",label:"Recruiting",procedures:[{id:"jd-writing-inclusive",title:"Write job descriptions candidates actually read",level:"foundation",minutes:30,description:"Outcome-focused, inclusive-language JDs that widen rather than shrink funnels.",tags:["job-description","inclusive-hiring"],steps:["Lead with impact: what will this person own and change in year one?","List must-haves ≤5; move nice-to-haves to a 'bonus' section","Strip coded language ('rockstar', 'aggressive'); run gender-decoder check","State salary range and process timeline upfront","Describe interview steps concretely so candidates can prepare","Test readability at grade 9 level; cut jargon"],pitfalls:["Ten-year requirement lists filtering out high-potential candidates","'Culture fit' phrasing inviting affinity bias"]},{id:"screening-bias-guards",title:"Screen resumes with bias guards",level:"intermediate",minutes:25,description:"Structured screening rubrics applied blind where feasible, reducing noise-based rejection.",tags:["screening","bias","recruiting"],steps:["Define rubric criteria tied to job outcomes before viewing resumes","Anonymize names/schools/photos during first pass where legal","Score independently; discuss only divergent cases","Weight demonstrated work over pedigree proxies","Log rejection reasons per stage; audit monthly for pattern drift","Keep pipeline data for adverse-impact analysis"],pitfalls:["Keyword filters rejecting qualified non-linear careers","Similarity attraction favoring resume mirrors"]}]},{id:"onboarding-offboarding",label:"Onboarding & Offboarding",procedures:[{id:"day-one-onboarding",title:"Deliver a first week that converts",level:"intermediate",minutes:30,description:"Pre-provisioned access, buddy assignment, and a shipped-by-Friday first task.",tags:["onboarding","retention"],steps:["Provision accounts/hardware BEFORE day one; verify login day zero","Assign an onboarding buddy separate from the manager","Schedule meet-and-greets with key collaborators week one","Ship something tiny to production by Friday","Day-5 pulse survey: clarity, belonging, blockers","Manager check-ins at 7/30/90 days against role expectations"],pitfalls:["Week one lost to access tickets","New hires reading docs alone for five days"]},{id:"graceful-offboarding",title:"Offboard gracefully and securely",level:"foundation",minutes:20,description:"Knowledge transfer, access revocation, and humane exits protecting everyone involved.",tags:["offboarding","security","knowledge-transfer"],steps:["Run exit knowledge-transfer checklist per owned system","Revoke access at separation hour: SSO, repos, VPN, cards","Transfer ownership of docs, cron jobs, vendor relationships","Exit interview focused on systemic learning, not venting capture","Alumni path: references, referral bonus, rehire eligibility stated","Audit orphaned accesses 30 days later"],pitfalls:["Departures discovering single-person knowledge lock-ins","Access lingering for months post-exit"]}]},{id:"policy-engagement",label:"Policy & Engagement",procedures:[{slug:"footprint-audit",authored:!0,id:"online-footprint-audit",title:"Audit an online professional footprint",level:"intermediate",minutes:40,description:"Verify claims, detect namesake contamination, and flag privacy leaks across public profiles. Use during background reviews, bio writing, personal-brand cleanups, or pre-publication fact checks.",tags:["research","verification","privacy","background-check"],steps:["Enumerate surfaces: code hosts, socials, blogs, portfolios, badge pages","Verify each claim at its primary source; record URL and date checked","Label every claim VERIFIED / UNVERIFIED / CONTAMINATED (namesake)","Search name + achievement pairs to catch other-person attribution","Flag leaked PII (phone, DOB) onto a takedown list — never republish it","Draft bios drawing ONLY from verified items with conservative rounding"],pitfalls:["Trusting AI answers blending namesakes","Republishing contact data because 'it is already public'"]},{id:"engagement-pulse-loops",title:"Run engagement pulse loops that change things",level:"intermediate",minutes:25,description:"Short surveys, visible actions, closed feedback loops — trust grows from evidence of listening.",tags:["engagement","surveys","culture"],steps:["Pulse 5-8 questions max, anonymous with cohort minimums (n≥5)","Ask about energy, clarity, growth, blockers — not pizza-party satisfaction","Share raw themes within one week, including uncomfortable ones","Pick ONE action per cycle with named owner and date","Report progress next cycle before collecting new data","Retire questions answered by shipped actions"],pitfalls:["Annual surveys whose results vanish into decks","Anonymous channels used for blame archaeology"]}]}]},{id:"healthcare-clinical",label:"Healthcare & Clinical",icon:"\uD83C\uDFE5",gradient:"from-rose-600 via-red-500 to-orange-500",ring:"ring-red-500/30",text:"text-red-400",blurb:"Clinical workflows, quality improvement, health informatics, and patient-communication craft.",roles:["Nurses","Physicians","Clinical Managers","Health Informaticists"],domains:[{id:"clinical-workflow",label:"Clinical Workflow",procedures:[{id:"shift-handoff-isbar",title:"Run structured shift handoffs with ISBAR",level:"foundation",minutes:20,description:"Transfer patient care using Identify-Situation-Background-Assessment-Recommendation so nothing critical drops between shifts.",tags:["handoff","safety","communication"],steps:["Identify: name, age, location, attending team for each patient","Situation: current diagnosis and reason for admission in one sentence","Background: relevant history, allergies, code status, isolation needs","Assessment: latest vitals trends and your clinical concern level","Recommendation: pending tasks, watch-fors, escalation thresholds","Receiver reads back action items before closing each handoff"],pitfalls:["Social chat interleaved with handoff losing structure","Vague watch-fors like 'if worse, call' without thresholds"]},{id:"med-rec-reconciliation",title:"Reconcile medications across transitions of care",level:"intermediate",minutes:30,description:"Build one verified medication list at every admission, transfer, and discharge.",tags:["medications","transitions","safety"],steps:["Take best-possible medication history from patient plus pharmacy records","Clarify discrepancies with prescriber before transcribing orders","Flag high-risk meds (anticoagulants, insulin, opioids) for double-check","Document intentional changes vs errors distinctly in the record","Counsel at discharge with teach-back on changed medications","Send reconciled list to the next provider AND community pharmacy"],pitfalls:["Copy-forward lists propagating stopped medications","Herbals/OTC never asked about, interacting with new scripts"]},{id:"deterioration-escalation",title:"Escalate deterioration early with objective triggers",level:"intermediate",minutes:25,description:"Use early-warning scores and defined thresholds so concern becomes action without hesitation cost.",tags:["deterioration","escalation","ews"],steps:["Track early-warning score trend, not single readings","Set personal trigger: score X or rise Y means senior review within Z minutes","Present escalation in ISBAR with the numbers that triggered you","Document time of concern, who notified, response received","If response inadequate, use chain-of-command explicitly — policy protects this","Debrief after events: what threshold would have fired earlier?"],pitfalls:["Normalizing gradual overnight decline across serial readings","Waiting for rounds when criteria already met"]}]},{id:"quality-informatics",label:"Quality & Informatics",procedures:[{id:"quality-improvement-cycle",title:"Lead a PDSA quality improvement cycle",level:"intermediate",minutes:40,description:"Small tested changes over big launches: plan-do-study-act cycles with measurable process metrics.",tags:["quality-improvement","pdsa","process"],steps:["Define problem with baseline data over sufficient weeks, not anecdotes","Pick ONE process change with a clear mechanism story","Plan: who measures what, when, predicted effect written beforehand","Do: pilot on one unit or one week; protect the experiment","Study: compare run-chart against baseline; look for special-cause variation","Act: adopt, adapt, or abandon honestly; document decision"],pitfalls:["Changing three things simultaneously, unlearnable results","Sustainability ignored after the pilot enthusiasm fades"]},{id:"cdss-alert-review",title:"Tune clinical decision support alerts responsibly",level:"advanced",minutes:40,description:"Reduce alert fatigue by measuring override reasons and retiring low-value interrupts.",tags:["cdss","alerts","informatics"],steps:["Pull override rates and documented reasons per alert type","Rank alerts by override rate \xd7 potential harm if heeded","Retire or narrow firing conditions of alerts overridden >90% safely","A/B tiered severity: interruptive only where harm is real","Monitor post-change for missed-event signals with named owner","Review the whole alert panel quarterly like a formulary"],pitfalls:["Adding new alerts without retiring any, ever","Interruptive warnings for documentation minutiae"]},{id:"patient-teach-back",title:"Teach-back patient education that lands",level:"foundation",minutes:20,description:"Confirm understanding by asking patients to explain back — without making it a quiz.",tags:["education","communication","health-literacy"],steps:["Chunk teaching to one concept at a time in plain language","Replace jargon: 'water pill' not 'diuretic', numbers with what they mean","Ask 'I want to check I explained well — how will you take this at home?'","Re-explain differently (not louder) whatever came back wrong","Provide one-page written summary at 6th-grade reading level","Involve caregiver present for the final teach-back round"],pitfalls:["'Any questions?' treated as comprehension verification","Handing printed sheets instead of confirming understanding"]}]}]},{id:"biotech-pharma",label:"Biotech & Pharma",icon:"\uD83E\uDDEC",gradient:"from-lime-500 via-green-500 to-emerald-500",ring:"ring-lime-500/30",text:"text-lime-400",blurb:"Bioinformatics workflows, lab informatics, and regulatory documentation discipline.",roles:["Bioinformaticians","Lab Scientists","Regulatory Affairs","Genetic Engineers","Clinical Data Managers"],domains:[{id:"bioinformatics",label:"Bioinformatics",procedures:[{id:"seq-qc-pipeline",title:"Quality-control sequencing data before analysis",level:"intermediate",minutes:45,description:"Read-level QC, adapter trimming, contamination screens, and reproducible QC reporting.",tags:["sequencing","qc","pipelines","ngs"],steps:["Run read-level QC: per-base quality, GC bias, duplication profiles","Trim adapters/low-quality tails with documented parameter versions","Screen contamination against expected organism panels","Verify reference genome build matches annotation versions exactly","Emit multi-sample QC summary tables for batch comparison","Pin tool versions in a workflow manager (Snakemake/Nextflow) for reruns"],pitfalls:["Mixed genome builds between alignment and annotation","Batch effects mistaken for biological signal"]},{id:"variant-calling-sop",title:"Standardize variant calling and annotation",level:"advanced",minutes:50,description:"Consistent callers, filters, and annotation sources so variant lists compare across runs.",tags:["variants","genomics","sop"],steps:["Fix caller versions and filter thresholds in writing before processing","Normalize representations (left-align, split multiallelics) consistently","Annotate against versioned databases recording exact release dates","Apply depth/quality filters appropriate to assay type","Validate a truth-set sample each run before trusting outputs","Store VCFs with full provenance: sample, pipeline hash, references"],pitfalls:["Annotation databases drifting between analyses","Filter tuning per-run destroying comparability"]},{id:"sequence-design-checks",title:"Run design-stage computational checks",level:"advanced",minutes:40,description:"In-silico screening of designed constructs: specificity scoring, off-target checks, and documentation gates — always paired with institutional biosafety approval.",tags:["design","crispr","in-silico","biosafety"],steps:["Confirm institutional biosafety committee approval covers this construct class","Score target specificity computationally; flag high-homology regions","Check designed elements for problematic repeats/restriction sites","Record every design parameter and tool version in the lab notebook system","Route flagged designs through supervisor review before any ordering","Archive sequences and rationales to the registered inventory"],pitfalls:["Skipping specificity screening because 'previous round worked'","Design records living only in chat threads"]}]},{id:"lab-informatics",label:"Lab Informatics",procedures:[{id:"eln-sample-lineage",title:"Track sample lineage end to end",level:"intermediate",minutes:35,description:"Aliquots, derivations, and storage positions recorded so any result traces to its origin.",tags:["elN","lims","sample-tracking"],steps:["Assign unique IDs at receipt; barcode physically and digitally","Record every derivation event: parent ID, process, date, operator","Track storage position changes like transactions, not overwrites","Enforce required fields at entry; free-text only for observations","Reconcile physical inventory vs system quarterly","Enable one-click lineage tree per final sample"],pitfalls:["Spreadsheet-as-LIMS with silent column drift","Pooled samples losing constituent IDs"]},{id:"protocol-versioning",title:"Version protocols like software",level:"foundation",minutes:25,description:"Controlled protocol documents, change logs, and effective-date discipline for reproducibility and audits.",tags:["protocols","documentation","reproducibility"],steps:["Store protocols in controlled repo with semver-style versions","Change log entry per revision: what changed, why, approved by","Effective dates govern which version applies to which experiment dates","Link executed runs to exact protocol version used","Retire superseded versions visibly, never silently edit history","Review critical protocols annually or upon equipment change"],pitfalls:["Protocol PDFs floating in email attachments","Edits without version bumps breaking audit trails"]}]},{id:"regulatory-clinical",label:"Regulatory & Clinical Data",procedures:[{id:"gxp-documentation",title:"Practice GxP-grade documentation habits",level:"intermediate",minutes:30,description:"ALCOA+ principles applied daily: attributable, legible, contemporaneous, original, accurate.",tags:["gxp","alcoa","documentation"],steps:["Record observations contemporaneously; backfilling is a finding","Sign/date entries; corrections use single-strike-through with reason","Keep raw data untouched; analysis works on labeled copies","Timestamps from controlled sources, not local clocks","Audit-trail reviews scheduled per system risk tier","Train every new team member on ALCOA+ with examples"],pitfalls:["Shared logins destroying attributability","'Cleanup' edits deleting raw anomalies"]},{id:"clinical-data-cleanliness",title:"Keep clinical trial data inspection-ready",level:"advanced",minutes:45,description:"Edit checks, discrepancy management, and lock discipline producing clean analyzable datasets.",tags:["clinical-data","edc","trials"],steps:["Configure edit checks at study build, not during enrollment","Triage discrepancies daily by query aging priority","Freeze database sections as they complete; control late changes","Document every protocol deviation with impact assessment","Run patient-profile reviews before any interim analysis","Rehearse the inspection story: request-to-record traceability demo"],pitfalls:["Queries opened months later eroding site trust","Unblinding incidents through careless report sharing"]}]}]},{id:"scientific-research",label:"Scientific Research",icon:"\uD83D\uDD2C",gradient:"from-cyan-500 via-sky-500 to-blue-500",ring:"ring-cyan-500/30",text:"text-cyan-400",blurb:"Study design, reproducibility, publication craft, and grant writing for research careers.",roles:["Researchers","PhD Students","Postdocs","Research Software Engineers"],domains:[{id:"study-design",label:"Study Design",procedures:[{id:"power-analysis-first",title:"Power studies before collecting a single datapoint",level:"foundation",minutes:30,description:"Effect-size estimates, power targets, and preregistration preventing underpowered regrets.",tags:["statistics","power","preregistration"],steps:["Estimate effect size from prior literature or pilot data honestly","Set α=0.05, power=0.80 minimum; compute required N per group","Account for expected attrition/contamination in recruitment numbers","Preregister hypotheses, exclusions, and analysis plan","Define stopping rules and interim analysis boundaries upfront","Archive design doc citable regardless of outcome"],pitfalls:["N=10 convenience samples dressed as exploratory","HARKing after unblinded looks at trends"]},{id:"control-condition-design",title:"Design controls that actually isolate variables",level:"intermediate",minutes:30,description:"Positive/negative controls, randomization, blinding choices matched to bias risks.",tags:["experimental-design","controls","bias"],steps:["List confounders specific to THIS setup, not textbook generics","Include negative control answering 'does anything respond?'","Include positive control proving assay sensitivity that day","Randomize sample placement/handling order where physical effects exist","Blind analyzers to condition labels during measurement","Pilot blind-unblinding differences once; document what you learned"],pitfalls:["All treated samples run on same day/batch plate","Analyst guessing conditions from subtle file naming"]}]},{id:"reproducibility",label:"Reproducibility",procedures:[{id:"computational-reproducibility",title:"Make computational results reproducible",level:"intermediate",minutes:40,description:"Environment pinning, deterministic pipelines, and one-command reruns from raw data.",tags:["reproducibility","pipelines","research-code"],steps:["Pin environments: lockfiles plus container image recorded per result","Version control everything including parameter files and seeds","Structure pipeline raw → processed → figures with explicit stages","Never edit intermediate files manually; regenerate instead","Test one-command rerun on clean machine before submission","Publish code/data under DOIs via archival repositories"],pitfalls:["'It works on my laptop' dependency webs","Figures hand-tweaked after generation"]},{id:"electronic-lab-notebook",title:"Keep lab notebooks worth citing",level:"foundation",minutes:25,description:"Daily entries linking intent, method versions, observations, and next actions.",tags:["lab-notebook","documentation"],steps:["Entry per session: goal, exact methods/versions, raw observations","Note failures fully — negative results are future time savers","Attach instrument outputs immediately with filenames explained","Sign/date entries; never backfill silently (GxP adjacent habit)","Index by experiment ID referenced everywhere else","Weekly review: unresolved questions become next week's plan"],pitfalls:["Notebook as polished rewrite losing real-time value","Critical parameters living only in memory"]}]},{id:"publication-grants",label:"Publication & Grants",procedures:[{id:"paper-writing-order",title:"Write papers in the order that works",level:"intermediate",minutes:40,description:"Figures first, methods while fresh, results mechanically, intro last — reducing revision churn.",tags:["writing","papers","publication"],steps:["Finalize figure set first; they ARE the story spine","Draft methods immediately while details are fresh","Write results referencing figures mechanically; interpretation comes later","Discussion maps each finding to literature honestly including conflicts","Introduction LAST: funnel from broad need to your gap","Abstract last-of-all: one sentence per section plus why-it-matters"],pitfalls:["Intro-first writing that changes after results solidify","Figure legends drafted separately from figures"]},{id:"grant-proposal-narrative",title:"Structure grant proposals reviewers score highly",level:"advanced",minutes:50,description:"Aims aligned to significance, feasibility evidence, and budget logic telling one coherent story.",tags:["grants","funding","writing"],steps:["Frame central question as one sentence a non-specialist grasps","3-4 aims building logically; each independently fundable-worthy","Pair every aim with approach + expected outcomes + alternatives","Prove feasibility: preliminary data, resources, timeline math","Budget narrative mirrors project narrative line by line","Circulate to two past reviewers BEFORE the deadline, not after rejection"],pitfalls:["Aims so ambitious reviewers doubt feasibility","Preliminary data buried instead of leading"]}]}]},{id:"finance-fintech",label:"Finance & Fintech",icon:"\uD83D\uDCB0",gradient:"from-green-500 via-emerald-500 to-lime-400",ring:"ring-emerald-500/30",text:"text-emerald-400",blurb:"Payment systems, risk controls, reconciliation, and financial modeling discipline.",roles:["Fintech Engineers","Financial Analysts","Risk Teams","Controllers"],domains:[{id:"payments-engineering",label:"Payments Engineering",procedures:[{id:"ledger-design-double-entry",title:"Design a double-entry ledger that balances forever",level:"advanced",minutes:45,description:"Immutable journal entries, balanced postings, and derived balances keeping money math provable.",tags:["ledger","payments","accounting"],steps:["Model money as immutable journal entries; never UPDATE amounts","Enforce sum(debits) = sum(credits) per transaction at DB level","Store original currency + rate snapshot per entry, not converted-only","Derive balances from entries; materialize views for speed, recompute nightly","Reconcile internal ledger to processor reports daily with diff alerts","Freeze periods: no edits into closed accounting periods, adjustments are new entries"],pitfalls:["Mutable balance columns drifting from entry truth","FX conversion applied twice across services"]},{id:"webhook-reliability-payments",title:"Process payment webhooks reliably",level:"intermediate",minutes:35,description:"Idempotent handlers, signature checks, and replay safety for provider callbacks.",tags:["webhooks","payments","reliability"],steps:["Verify signatures first; reject before any parsing side effects","Persist raw event immediately, acknowledge fast, process async","Deduplicate on event ID; assume providers retry aggressively","Handle out-of-order events via state machine per payment object","Backfill job reconciles missed webhooks against provider API hourly","Alert on processing lag and dead-letter depth, not just failures"],pitfalls:["Business logic inside webhook handler timing out mid-write","Trusting event arrival order for status transitions"]},{id:"reconciliation-flow",title:"Build daily reconciliation that catches drift",level:"intermediate",minutes:35,description:"Three-way match between internal ledger, processor settlement, and bank statements.",tags:["reconciliation","finance-ops"],steps:["Normalize all three sources to one canonical schema with IDs preserved","Match on reference IDs first, then fuzzy-match residuals by amount+date window","Categorize breaks: timing, fees missing, duplicates, true mismatches","Auto-resolve known-benign classes (settlement T+1) with aging limits","Route aged breaks to humans with full context attached","Publish break-rate trend weekly; sudden spikes mean upstream change"],pitfalls:["Manual spreadsheet reconciliation hiding systemic issues","Fee lines unmatched forever, polluting true mismatch counts"]}]},{id:"risk-modeling",label:"Risk & Modeling",procedures:[{id:"fraud-rules-vs-model",title:"Layer fraud rules under an ML model sensibly",level:"advanced",minutes:40,description:"Deterministic guardrails plus scored models with human review queues tuned by loss vs friction.",tags:["fraud","risk","ml"],steps:["Start with hard rules for non-negotiables (sanctions, velocity caps)","Score remaining traffic with a model trained on confirmed labels only","Define review queue capacity; set threshold to match it, not aspiration","Measure false-positive friction cost alongside fraud loss prevented","Champion-challenger rule/model changes in shadow mode first","Feed analyst outcomes back into labels weekly, closing the loop"],pitfalls:["Blocking based on proxy features discriminating protected groups","Thresholds tuned once and forgotten as patterns shift"]},{id:"financial-model-hygiene",title:"Keep financial models auditable",level:"foundation",minutes:30,description:"Structure assumptions, flows, and outputs so anyone can trace every number.",tags:["modeling","excel","analysis"],steps:["Separate inputs / calculations / outputs into distinct sections or sheets","One assumption cell referenced everywhere; no hardcoded duplicates","Color convention: blue inputs, black formulas, green cross-links","Sanity-check row: units, period alignment, growth vs inflation consistency","Stress test: flex the two biggest drivers \xb130% and observe covenants","Version with changelog tab; archive prior versions read-only"],pitfalls:["Circularity hacks breaking recalculation","Someone typing over a formula cell during a busy close"]},{id:"unit-economics-tracking",title:"Instrument unit economics honestly",level:"intermediate",minutes:30,description:"Per-order/per-user contribution margin including hidden costs investors will find anyway.",tags:["unit-economics","metrics","finance"],steps:["Define the unit precisely (order? active user? subscription-month?)","Include payment fees, support allocation, refunds/chargebacks in COGS","Segment margin by cohort and channel; blended averages lie","Track CAC payback months separately from LTV ratios","Reconcile product analytics revenue to finance books monthly","Revisit contribution margins quarterly as pricing and costs move"],pitfalls:["Gross revenue celebrated while contribution is negative","Refund/chargeback losses excluded from dashboards"]}]}]},{id:"real-estate",label:"Real Estate",icon:"\uD83C\uDFD8️",gradient:"from-lime-600 via-emerald-500 to-teal-400",ring:"ring-lime-500/30",text:"text-lime-400",blurb:"Deal analysis, listing craft, market comps, and client representation done ethically.",roles:["Agents","Investors","Property Managers","Analysts"],domains:[{id:"deal-analysis",label:"Deal Analysis",procedures:[{id:"property-underwriting-checklist",title:"Underwrite a rental property in one pass",level:"intermediate",minutes:40,description:"Income, expense reality, financing, and downside cases producing a defensible go/no-go.",tags:["underwriting","rentals","analysis"],steps:["Verify income with leases + market rents, not seller pro-forma","Budget expenses honestly: taxes, insurance, capex reserves, vacancy allowance","Model financing at TODAY's rates plus 100bps stress","Compute cash-flow after ALL costs; ignore appreciation in year-1 math","Run downside case: vacancy doubles, major capex hits — survivable?","Write investment thesis memo; if you can't defend it, pass"],pitfalls:["Seller pro-formas accepted as underwriting","Capex 'surprises' that any roof/HVAC inspection predicted"]},{id:"comps-analysis-rigorous",title:"Pull comps that actually justify price",level:"foundation",minutes:25,description:"Comparable selection by similarity and recency, adjusted transparently.",tags:["comps","valuation","market"],steps:["Filter to same submarket within 0.5mi and 90 days where inventory allows","Match on bed/bath/GLA/lot first; style second","Adjust for condition differences with documented per-item estimates","Drop outlier sales unexplained by visible factors","Weight closest-and-newest heaviest; show the grid","State confidence range; thin comp sets widen it honestly"],pitfalls:["Cherry-picked high comps justifying wishful list prices","Foreclosures mixed silently into arms-length sets"]},{slug:"renovation-roi-triage",id:"reno-roi",title:"Triage renovations by ROI before spending",level:"intermediate",minutes:30,description:"Cost-vs-value ranking separating value-adding work from personal-preference spending.",tags:["renovation","roi","flipping"],steps:["Fix safety/functionality first: they gate every sale regardless of ROI tables","Rank cosmetic work by local cost-vs-value report data","Get three contractor bids minimum; verify licenses and timelines","Hold a 15% contingency on every scope, non-negotiable","Stage the two rooms photography sells: kitchen and primary bath decisions","Track actuals vs estimate per line for your next deal's calibration"],pitfalls:["Over-improving past neighborhood ceiling price","Scope creep via 'while we're at it' change orders"]}]},{id:"clients-listings",label:"Clients & Listings",procedures:[{id:"listing-copy-that-sells",title:"Write listings buyers actually click",level:"foundation",minutes:20,description:"Lead with lifestyle outcome, structure scannable facts, and never oversell the flaws away.",tags:["copywriting","listings","marketing"],steps:["Headline = strongest verifiable hook (view, lot, layout) not 'stunning'","First paragraph paints morning/evening living there specifically","Facts block scannable: beds/baths/GLA/year/lot/parking up top","Replace adjectives with evidence ('granite' beats 'luxurious')","Disclose known issues plainly — trust converts better than surprise","Pair every room photo order with matching copy sequence"],pitfalls:["Adjective soup saying nothing checkable","Hiding flaws that inspections surface anyway, torching deals"]},{id:"buyer-representation-discipline",title:"Represent buyers with fiduciary discipline",level:"intermediate",minutes:30,description:"Needs discovery, honest property assessments, and negotiation advocacy documented properly.",tags:["buyers","ethics","negotiation"],steps:["Discovery beyond budget: timeline, must-haves, deal-breakers, decision process","Preview properties against THEIR criteria; reject mismatches proactively","Point out cons as readily as pros — reputation compounds over decades","Prepare offers from comps YOU verified, not asking-price anchoring","Negotiate repairs with contractor quotes attached, not vibes","Document advice given; agency means records"],pitfalls:["Steering toward own listings over fit","Waiving inspections without explaining specific risks"]}]}]},{id:"legal-compliance",label:"Legal & Compliance",icon:"⚖️",gradient:"from-yellow-500 via-amber-500 to-orange-500",ring:"ring-yellow-500/30",text:"text-yellow-400",blurb:"Contract review, privacy compliance, and IP hygiene for technical teams. Educational workflows, not legal advice.",roles:["Legal Ops","Privacy Officers","Compliance Teams","Founders","Engineers"],domains:[{id:"privacy-data",label:"Privacy & Data Protection",procedures:[{id:"data-mapping-gdpr",title:"Map personal data flows for GDPR readiness",level:"intermediate",minutes:45,description:"Inventory of what personal data exists, where it flows, on what basis — the foundation of every privacy program.",tags:["gdpr","privacy","data-mapping"],steps:["Inventory systems holding personal data with owners per store","Classify data categories: identity, behavioral, special categories","Document lawful basis per processing purpose; no 'legitimate interest' dumping","Map cross-border transfers with safeguard mechanisms noted","Record retention periods and deletion mechanics per category","Review the map quarterly and at every new integration"],pitfalls:["Shadow SaaS tools missing from the map entirely","Retention 'indefinite' defaults in databases"],kpis:["100% systems mapped with owners","Zero unmapped processors"]},{id:"dsar-response-flow",title:"Answer data subject requests within deadlines",level:"intermediate",minutes:35,description:"Intake, verification, retrieval, and response workflow meeting statutory clocks without panic.",tags:["dsar","privacy","process"],steps:["Stand up one intake channel logging request date automatically","Verify identity proportionate to data sensitivity","Search ALL systems from your data map, including backups policies","Redact third-party personal data before release","Respond within one month (GDPR), documenting extensions if complex","Log every request + outcome as audit evidence"],pitfalls:["Email archives forgotten in searches","Free-form responses creating new compliance issues"]},{id:"privacy-by-design-review",title:"Run privacy reviews inside feature development",level:"advanced",minutes:30,description:"Shift privacy questions into design docs so answers shape architecture, not patches.",tags:["privacy-by-design","dpiat","product"],steps:["Add privacy section to PRD template: data collected, purpose, retention","Trigger full assessment when new data categories or sharing emerge","Prefer client-side computation when feasible over collecting raw data","Minimize: collect only fields a defined purpose consumes","Wire consent flags into actual code paths, not just UI copy","Re-assess when vendors change subprocessor chains"],pitfalls:["Consent banners lying about actual SDK behavior","Analytics collecting more than documented"]}]},{id:"contracts-ip",label:"Contracts & IP",procedures:[{id:"msa-redline-triage",title:"Triage vendor MSA redlines fast",level:"intermediate",minutes:40,description:"Deal-breaker checklist separating acceptable edits from escalations in vendor paper.",tags:["contracts","negotiation","vendors"],steps:["Fix your walk-away list first: liability cap, indemnity scope, data rights","Compare against playbook positions; mark green/yellow/red per clause","Escalate only reds with proposed alternative language ready","Check auto-renewal and price-escalation clauses explicitly","Verify assignment/change-of-control terms against acquisition plans","Store executed versions searchable by clause type"],pitfalls:["Unlimited liability accepted via boilerplate oversight","Vendor-owned feedback clauses covering YOUR improvements"]},{id:"ip-assignment-hygiene",title:"Keep IP assignment clean across contributors",level:"foundation",minutes:25,description:"Employer agreements, contractor IP clauses, and open-source license discipline protecting company assets.",tags:["ip","open-source","licensing"],steps:["Every contributor signs IP assignment or proper license grant pre-work","Track open-source usage per repo with license compatibility notes","Ban copyleft-incompatible imports into proprietary components via CI checks","Record third-party assets (fonts, images) with license proofs","Audit contractor deliverables for embedded unlicensed dependencies","Maintain NOTICE files accurately for distributed software"],pitfalls:["GPL code linked into SaaS proprietary services","'Work made for hire' assumptions without written assignments"]}]}]},{id:"qa-testing",label:"QA & Testing",icon:"\uD83E\uDDEA",gradient:"from-teal-500 via-emerald-500 to-green-500",ring:"ring-teal-500/30",text:"text-teal-400",blurb:"Test strategy, automation pyramids, exploratory craft, and release confidence.",roles:["QA Engineers","SDETs","Test Automation Engineers","Developers"],domains:[{id:"test-strategy",label:"Test Strategy",procedures:[{id:"test-pyramid-balance",title:"Balance the test pyramid for your app",level:"foundation",minutes:30,description:"Allocate unit/integration/e2e counts by feedback speed and failure diagnosability.",tags:["testing","pyramid","strategy"],steps:["Default ratio: ~70% unit, ~20% integration, ~10% e2e — adjust per risk","Push logic coverage down; keep e2e for critical user journeys only","Integration tests own API contracts and database interactions","One smoke e2e suite under 5 min gates every deploy","Delete redundant tests asserting the same behavior at multiple levels","Review distribution quarterly as architecture evolves"],pitfalls:["Ice-cream-cone suites: thousands of slow UI tests","Unit tests mocking everything, testing nothing real"]},{id:"risk-based-testing",title:"Prioritize testing by risk, not habit",level:"intermediate",minutes:25,description:"Failure likelihood \xd7 impact matrix focusing effort where bugs hurt most.",tags:["risk","prioritization","qa"],steps:["List modules; score failure probability from change frequency + complexity","Score business impact: money paths, data integrity, legal exposure first","Matrix top-right quadrant gets deepest coverage and fastest fixes","New features inherit high risk scores until proven stable","Revisit after every incident; incidents reveal mis-scored areas","Publish the matrix so devs understand review depth expectations"],pitfalls:["Equal test depth everywhere = shallow where it matters","Legacy untouched code tested ritually"]}]},{id:"automation",label:"Test Automation",procedures:[{id:"flaky-test-elimination",title:"Eliminate flaky tests systematically",level:"advanced",minutes:40,description:"Quarantine, root-cause classes, and stabilization patterns restoring CI trustworthiness.",tags:["flaky-tests","ci","reliability"],steps:["Auto-detect flakiness via retry-pass detection; report rate weekly","Quarantine flaky tests immediately — a red CI must mean something","Root-cause by class: timing/sleep → explicit waits; order-dependence → isolation","Fix test-data collisions with unique-per-run factories","Stabilize environment noise: ports, clocks, network mocks","Burn down quarantine weekly; two-strikes rule for chronic offenders"],pitfalls:["Auto-retry hiding flake instead of surfacing it","Deleting flaky tests silently losing coverage"]},{id:"e2e-maintainable-selectors",title:"Write E2E tests that survive redesigns",level:"intermediate",minutes:35,description:"User-visible locators, page objects done right, and assertions on outcomes not implementation.",tags:["e2e","playwright","selectors"],variants:{playwright:{id:"pw",label:"Playwright",adds:["Prefer getByRole/getByLabel over CSS/XPath chains","Use web-first assertions auto-waiting instead of sleeps"]},cypress:{id:"cypress",label:"Cypress",adds:["Avoid conditional control-flow; command determinism wins","Intercept network for deterministic state setup"]}},description:"Selector strategy and structure choices keeping end-to-end suites maintainable through UI churn.",tags:["e2e","maintainability"],steps:["Locate elements by accessible role/name — resilient AND forces a11y","Ban generated class names and nth-child position selectors","Model flows in helpers once; tests read as user intent scripts","Assert observable outcomes (row appears) over DOM internals","Seed state via APIs/fixtures, never UI-only setup chains","Keep each spec independent: any subset passes on fresh context"],pitfalls:["Page objects becoming second app full of logic","Chained UI setups breaking one hop upstream"]}]},{id:"exploratory-release",label:"Exploratory & Release",procedures:[{id:"session-based-exploratory",title:"Run session-based exploratory testing",level:"intermediate",minutes:35,description:"Charter-driven timeboxed sessions producing documented findings, not random clicking.",tags:["exploratory-testing","sessions","qa"],steps:["Write charters: 'Explore X with Y focus using Z resources'","Timebox 60-90 min sessions; split if unfocused","Log notes live: what tried, what observed, questions raised","Debrief findings into tickets immediately with repro steps","Vary personas/data/environment per session rotation","Track charter coverage to expose unexplored corners"],pitfalls:["Exploratory as unplanned filler when automation lags","Findings lost in prose nobody triages"]},{id:"release-readiness-review",title:"Gate releases with a readiness review",level:"foundation",minutes:25,description:"Checklist verdicts across quality signals making go/no-go boring and defensible.",tags:["release","gates","process"],steps:["Collect: automated pass rates, open severity counts, perf deltas","Verify rollback plan exists and was rehearsed this cycle","Confirm monitoring dashboards updated for new surfaces","Legal/support/comms sign-offs for customer-visible changes","Decision recorded with dissent noted — no silent overrides","Post-release retro compares predicted vs actual issues"],pitfalls:["Go/no-go theater after decision already made upstream","Severity-3 backlog blocking honest signal reading"]}]}]},{id:"technical-writing",label:"Technical Writing",icon:"✍️",gradient:"from-orange-500 via-red-400 to-pink-500",ring:"ring-orange-500/30",text:"text-orange-400",blurb:"Docs systems, API references, tutorials, and developer marketing that people finish reading.",roles:["Technical Writers","Developer Advocates","Engineers Who Document","Content Leads"],domains:[{id:"docs-systems",label:"Documentation Systems",procedures:[{id:"diataxis-audit",title:"Sort docs into types readers recognize",level:"foundation",minutes:30,description:"Tutorials vs how-tos vs reference vs explanation — separating modes ends most doc confusion.",tags:["diataxis","information-architecture"],steps:["Label every existing page: learning-journey, task-recipe, information-lookup, or theory","Flag pages mixing modes; split at natural seams","Write one flagship tutorial covering the happy path end-to-end","Move edge-case handling into linked how-to recipes","Generate reference mechanically from source where possible","Add 'which page do I need?' router for newcomers"],pitfalls:["Tutorials stuffed with tangents breaking flow","Reference prose explaining philosophy nobody asked"]},{id:"docs-as-code-workflow",title:"Run docs through the same pipeline as code",level:"intermediate",minutes:30,description:"Versioned markdown, PR reviews, link checks, and preview deploys keeping docs trustworthy.",tags:["docs-as-code","ci","markdown"],steps:["Store docs beside code or in sibling repo with same review gates","CI checks links, style rules, and builds previews per PR","Enforce frontmatter metadata: owner, last-verified date, audience","Broken-build rule applies: failing docs checks block merges","Auto-generate changelog-driven updates for API surfaces","Quarterly stale-sweep: unverified pages get flagged visibly"],pitfalls:["Wiki graveyards outside any workflow","Screenshots rotting after every UI release"]}]},{id:"api-reference",label:"API Reference & Guides",procedures:[{id:"endpoint-doc-pattern",title:"Document endpoints developers can copy-paste",level:"intermediate",minutes:30,description:"Every endpoint documented with working request, realistic response, and error table.",tags:["api-docs","openapi"],steps:["Lead with minimal working request using realistic sandbox data","Show full response body, not truncated ellipses","Error section lists codes with causes AND fixes","Note rate limits, auth scopes, and idempotency behavior inline","Provide copyable snippets in three top languages minimum","Test every example in CI against staging nightly"],pitfalls:["Examples with fake keys that fail when tried","Parameter tables without units or formats"]},{id:"tutorial-craft",title:"Write tutorials people actually finish",level:"intermediate",minutes:35,description:"Fast first win, verifiable checkpoints, and failure exits keeping momentum.",tags:["tutorials","onboarding","dx"],steps:["Promise specific outcome in title; deliver it under 15 minutes","Show expected result early with screenshot of finished state","Verify-everything: each step includes what user should see","Number recovery paths for common failures inline","Cut every sentence not moving toward the promised outcome","Test with two fresh users watching silently; fix stumbles"],pitfalls:["Prerequisite walls before first success","'Simply' doing invisible multi-step things"]}]},{id:"dev-content",label:"Dev Content & Advocacy",procedures:[{slug:"bug-story-post",authored:!0,id:"debugging-story-post",title:"Turn a debugging war story into a post",level:"foundation",minutes:40,description:"Structure bug-hunt experiences into engaging technical posts that teach method, not just drama. Use when writing dev blogs, hackathon retrospectives, or 'how I fixed X' content.",tags:["blogging","storytelling","devrel"],steps:["Open mid-action: the symptom that ruined your day, concretely","Reconstruct hunt as numbered hypotheses with evidence for/against","Show the misleading path you took — readers learn most there","Reveal root cause with the minimal repro snippet","Extract 2-3 transferable lessons beyond this specific bug","End with prevention checklist readers can adopt today"],pitfalls:["Chronological dumps including irrelevant detours","Lessons so generic they fit any story"]},{id:"changelog-users-read",title:"Write changelogs users read",level:"foundation",minutes:20,description:"User-outcome phrasing, migration notes, and consistent categories building release trust.",tags:["changelog","release-notes"],steps:["Categorize: Added / Changed / Fixed / Breaking / Security only","Phrase entries as user outcomes, not commit messages","Breaking changes lead with migration snippet and deadline","Link each entry to PR/docs for depth-seekers","Keep voice consistent; assign one editor per release","Never ship silent dependency bumps past Security category"],pitfalls:["'Misc fixes and improvements' filler sections","Breaking changes discovered at runtime"]}]}]},{id:"marketing-growth",label:"Marketing & Growth",icon:"\uD83D\uDCE3",gradient:"from-orange-400 via-amber-400 to-yellow-300",ring:"ring-orange-500/30",text:"text-orange-400",blurb:"Positioning, content engines, lifecycle funnels, and campaign measurement that compounds.",roles:["Growth Marketers","Content Strategists","Lifecycle Marketers","Founders"],domains:[{id:"positioning-content",label:"Positioning & Content",procedures:[{id:"messaging-hierarchy",title:"Build a messaging hierarchy from customer language",level:"intermediate",minutes:35,description:"One-liner → proof pillars → objection handling, mined verbatim from real buyer words.",tags:["messaging","positioning","copywriting"],steps:["Harvest verbatims: sales calls, reviews, support tickets, churn surveys","Cluster by desired outcome, not feature vocabulary","Draft one-liner: for WHO who struggle with WHAT, we deliver OUTCOME unlike ALTERNATIVE","Support with three proof pillars, each backed by evidence artifact","List top objections with honest counters — including when NOT to buy","Test on 5 cold visitors: can they repeat what you do in their words?"],pitfalls:["Internal jargon customers never use","Claim soup: nine benefits competing for the headline"]},{id:"content-engine-compounding",title:"Run a content engine that compounds",level:"intermediate",minutes:40,description:"Topic clusters, refresh cycles, and distribution loops turning articles into an asset base.",tags:["content-marketing","seo","distribution"],steps:["Map pillar topics to buyer journey stages; own 2-3 pillars deeply","Interlink cluster content to pillar hubs deliberately","Ship on cadence you can sustain for a year, not a sprint month","Distribute each piece 5 ways: newsletter, socials, communities, repurposed clips, syndication","Refresh top decile performers quarterly instead of always creating new","Track assisted conversions, not last-click vanity"],pitfalls:["Publishing into the void without distribution loops","Chasing volume until topical authority dilutes"]}]},{id:"lifecycle-campaigns",label:"Lifecycle & Campaigns",procedures:[{id:"lifecycle-email-flows",title:"Architect lifecycle email flows that respect inboxes",level:"intermediate",minutes:35,description:"Onboarding, activation, retention, win-back sequences triggered by behavior not calendars alone.",tags:["email","lifecycle","automation"],steps:["Map triggers to behavioral milestones (signed up, invited team, went quiet)","Onboarding sequence drives to ONE activation action per email","Branch content by role/use-case data already collected","Sunset rules: disengage non-openers after N touches to protect deliverability","Win-back offers differ from onboarding offers — test separately","Review flow metrics monthly: open→click→conversion per step"],pitfalls:["Daily nurture cadence training people to unsubscribe","One generic drip pretending all users are identical"]},{id:"campaign-measurement-plan",title:"Design campaign measurement before launching",level:"foundation",minutes:30,description:"Hypothesis, KPI tree, tracking implementation, and readout date committed upfront.",tags:["analytics","campaigns","attribution"],steps:["Write hypothesis: audience X + message Y through channel Z yields metric delta","Define primary KPI and guardrails (unsubscribe rate, CAC ceiling)","Implement UTM taxonomy documented centrally — no freeform tags","Verify tracking fires correctly BEFORE spend starts","Set minimum sample/duration for any conclusion; note it in calendar","Readout includes confidence statement and next-test proposal"],pitfalls:["Post-hoc channel credit claimed from correlation","Tracking broken discovered at readout time"]}]}]},{id:"startup-founders",label:"Startup & Founders",icon:"\uD83D\uDE80",gradient:"from-fuchsia-500 via-purple-500 to-indigo-500",ring:"ring-fuchsia-500/30",text:"text-fuchsia-400",blurb:"MVP shipping, validation, fundraising narratives, and early growth loops.",roles:["Founders","Indie Hackers","Early Employees","Solopreneurs"],domains:[{id:"validation-mvp",label:"Validation & MVP",procedures:[{id:"mvp-scope-cutting",title:"Cut MVP scope without cutting the point",level:"foundation",minutes:25,description:"Identify the single riskiest assumption and build only what tests it.",tags:["mvp","lean","scope"],steps:["Write the riskiest assumption sentence: 'This works if…'","List features; mark each as assumption-tester or decoration","Cut decorations ruthlessly for v1 — even obvious-seeming ones","Prefer concierge/manual versions over automation initially","Define success signal BEFORE launch: threshold, timeframe, metric","Timebox build to weeks not months; deadline forces clarity"],pitfalls:["Auth systems built before problem validation","MVPs so minimal they cannot test the actual hypothesis"]},{id:"problem-validation-signals",title:"Read validation signals honestly",level:"intermediate",minutes:25,description:"Distinguish politeness from pull using behavior-based criteria.",tags:["validation","customers","signals"],steps:["Count actions, not compliments: pre-orders, waitlist signups, LOIs","Weight paid experiments over free interest every time","Track unsolicited follow-ups; pull shows up unprompted","Interview churned/declined prospects more than fans","Set kill criteria upfront to fight sunk-cost bias","Review signal log weekly; patterns beat anecdotes"],pitfalls:["Mom-test failures: friends saying it's nice","Interpreting survey enthusiasm as demand"]}]},{id:"growth-fundraising",label:"Growth & Fundraising",procedures:[{id:"founder-narrative-deck",title:"Build a founder narrative deck",level:"intermediate",minutes:40,description:"12 slides answering investor questions in order: why now, why you, why this market.",tags:["pitch-deck","fundraising","narrative"],steps:["Slide order: problem, insight, solution, demo, market entry, business model, traction, team, ask","Lead every slide with the headline takeaway sentence","Traction slide uses honest numbers trending up, annotated spikes","'Why now' needs a concrete shift: tech cost curve, regulation, behavior","Ask slide: amount → milestones → runway math visible","Appendix carries depth; main deck stays 12-15 slides"],pitfalls:["Feature tours instead of narrative arcs","Vanity metrics (downloads) where revenue belongs"]},{id:"first-growth-loop",title:"Find your first repeatable growth loop",level:"advanced",minutes:35,description:"One channel executed deeply beats five dabbling channels; instrument the loop end-to-end.",tags:["growth","marketing","distribution"],steps:["List candidate loops: SEO/content, communities, partnerships, referrals, PLU product hooks","Pick one matching founder strengths + audience habitat","Instrument full loop: touch → visit → signup → activation → share","Run 4-week sprint with weekly output targets, review honestly","Double down only when loop math shows compounding signs","Kill or iterate; dabbling across channels is the failure mode"],pitfalls:["Channel-hopping weekly resetting all learning to zero","Growth tactics before retention exists"]}]}]},{id:"sales-success",label:"Sales & Customer Success",icon:"\uD83E\uDD1D",gradient:"from-lime-500 via-green-400 to-emerald-300",ring:"ring-lime-500/30",text:"text-lime-400",blurb:"Consultative selling, discovery calls, pipeline hygiene, and retention playbooks.",roles:["Account Executives","Customer Success Managers","Sales Engineers","Founders Selling"],domains:[{id:"discovery-deal",label:"Discovery & Deals",procedures:[{id:"discovery-call-framework",title:"Run discovery that surfaces real buying motives",level:"foundation",minutes:30,description:"Question ladders from situation to impact to cost-of-inaction, with talk-ratio discipline.",tags:["sales","discovery","qualification"],steps:["Open with agenda contract: their goals, your questions, next-step decision at end","Climb ladder: current state → why now → attempted fixes → cost of status quo","Quantify impact in THEIR metric (hours lost, revenue delayed)","Keep talk ratio ≤40%; silence is a discovery tool","Test budget/authority indirectly through process questions ('who else weighs in?')","Close with mutual action plan draft, not a generic 'send you info'"],pitfalls:["Demo-dumping before problem is quantified","Accepting 'interesting' as forward motion"]},{id:"pipeline-hygiene-review",title:"Review pipeline with honest hygiene standards",level:"intermediate",minutes:25,description:"Stage-exit criteria, next-step currency, and slippage detection keeping forecasts real.",tags:["pipeline","forecast","process"],steps:["Define exit criteria per stage; deals without them get downgraded automatically","Every open deal carries dated next step; no next step = stalled flag","Track stage-conversion and cycle-time by segment monthly","Flag slipped-close-date deals for win/loss review regardless of outcome","Forecast three numbers: commit / best-case / worst-case with rationale","Remove wishful deals ruthlessly; clean pipe beats fat pipe"],pitfalls:["Happy-ears stage inflation before quarter end","Dead deals parked forever muddying conversion metrics"]},{id:"objection-reframe",title:"Handle objections without groveling or dodging",level:"intermediate",minutes:20,description:"Acknowledge → clarify → reframe to the underlying concern → evidence → confirm resolution.",tags:["objections","negotiation","communication"],steps:["Acknowledge genuinely; defensiveness kills trust instantly","Clarify what's UNDER the stated objection (price often means unproven value)","Reframe against the cost of the status quo they already quantified","Offer specific evidence matched to objection type (case study, trial, SLA)","Confirm the objection is resolved explicitly before moving on","Log objections verbatim weekly — they're roadmap gold"],pitfalls:["Instant discounting as reflex response to price pushback","Arguing the objection away instead of exploring it"]}]},{id:"retention-expansion",label:"Retention & Expansion",procedures:[{id:"churn-risk-signal-system",title:"Build a churn-risk signal system",level:"advanced",minutes:35,description:"Leading indicators, health scores, and intervention triggers acting before renewal panic.",tags:["churn","customer-success","retention"],steps:["Interview churned customers; extract 5 leading behavioral signals","Weight signals into transparent health score (usage depth, support tone, champions leaving)","Set intervention playbook per risk tier with owners and SLAs","Trigger executive outreach on champion-departure signal specifically","Measure save-rate per intervention type; prune theater","Feed outcomes back into score weights quarterly"],pitfalls:["Black-box scores CSMs don't trust or use","Renewal-week scramble replacing year-round signals"]},{id:"qbr-that-expands",title:"Run business reviews that expand accounts",level:"intermediate",minutes:30,description:"Value-delivery narratives with customer metrics turning renewals into growth conversations.",tags:["qbr","expansion","account-management"],steps:["Open with THEIR goals restated; measure everything against them","Show adoption vs success benchmarks with concrete usage stories","Quantify delivered value in customer's own KPIs, co-owned numbers","Surface untapped use cases mapped to unmet goals","Propose next-quarter success plan requiring specific commitments","Multi-thread: new stakeholders present every review"],pitfalls:["Feature-update decks nobody reads","Single-threaded relationships evaporating on champion exit"]}]}]},{id:"freelance-business",label:"Freelance & Business",icon:"\uD83D\uDCBC",gradient:"from-purple-500 via-pink-500 to-rose-500",ring:"ring-purple-500/30",text:"text-purple-400",blurb:"Proposals, pricing, client management, and contracts for independent professionals.",roles:["Freelancers","Consultants","Agencies","Independent Developers"],domains:[{id:"winning-clients",label:"Winning Clients",procedures:[{id:"proposal-that-closes",title:"Write proposals that close without discounting",level:"intermediate",minutes:35,description:"Outcome-first structure, option pricing, and risk reversal moving decisions forward.",tags:["proposals","sales","pricing"],steps:["Mirror their words for problem statement before any solution talk","Present outcome and business impact, not deliverable lists","Offer three options anchoring middle as intended choice","State price confidently after value; never apologize in writing","Include scope fences and change-request process explicitly","Set decision deadline with reason; follow up twice max"],pitfalls:["Hourly itemization inviting line-item negotiation","Free strategy dumped into RFP replies"]},{id:"positioning-niche",title:"Position into a profitable niche",level:"foundation",minutes:30,description:"Specific expertise \xd7 audience \xd7 outcome claims commanding premium rates.",tags:["positioning","branding","strategy"],steps:["Fill formula: 'I help [audience] achieve [outcome] through [means]'","Validate niche pays: find three competitors charging well already","Rewrite profiles/bio to niche voice everywhere consistently","Collect proof artifacts: case studies, before/after metrics","Publish niche-specific content answering buyer questions","Review annually; niches mature and shift"],pitfalls:["Generalist positioning competing on price alone","Niche picked where YOU like work but buyers don't pay"]}]},{id:"client-delivery",label:"Client Delivery",procedures:[{id:"scope-change-control",title:"Control scope creep professionally",level:"intermediate",minutes:25,description:"Change requests, written confirmations, and tradeoff framing protecting margins and relationships.",tags:["scope","contracts","communication"],steps:["SOW lists explicit exclusions, not just inclusions","Log every 'small favor' request in a visible tracker","Respond to creep with options: add budget, swap scope, or phase later","Confirm any verbal changes in same-day recap email","Re-baseline timeline visibly when scope changes materially","Debrief post-project: where creep entered, plug that door"],pitfalls:["Absorbing 'quick fixes' until resentment explodes","Change requests raised at invoice time"]},{id:"pricing-for-value",title:"Price on value with floor discipline",level:"advanced",minutes:30,description:"Rate math from costs + target income, value anchors, and walk-away floors.",tags:["pricing","rates","negotiation"],steps:["Compute cost floor: expenses + taxes + non-billable time \xf7 billable hours","Research market band for your niche's outcomes, not hours","Anchor to value created: revenue gained or cost removed estimates","Raise rates each time pipeline exceeds capacity sustainably","Never discount price; reduce scope instead when pressured","Track effective hourly rate per project; prune loss leaders"],pitfalls:["Competitor-undercutting spirals to unsustainability","Senior expertise priced off junior hour tables"]}]}]},{id:"education-learning",label:"Education & Teaching",icon:"\uD83C\uDF93",gradient:"from-amber-400 via-yellow-400 to-orange-300",ring:"ring-amber-500/30",text:"text-amber-400",blurb:"Lesson design, assessment craft, classroom management, and online-course production.",roles:["Teachers","Instructional Designers","Course Creators","Trainers"],domains:[{id:"instructional-design",label:"Instructional Design",procedures:[{id:"learning-objectives-measurable",title:"Write learning objectives you can actually assess",level:"foundation",minutes:25,description:"Observable-verb objectives aligned to assessments so teaching, testing, and claims match.",tags:["objectives","curriculum","assessment"],steps:["State who will do what observable action by when","Use measurable verbs (derive, compare, debug) not fog (understand, appreciate)","Set the difficulty level honestly against learner prerequisites","Map every objective to at least one assessment item","Delete objectives nothing assesses; they waste student attention","Sequence objectives so each builds on demonstrated prior mastery"],pitfalls:["'Students will understand X' — untestable and unteachable","Assessments measuring reading skill instead of target skill"]},{id:"lesson-plan-craft",title:"Design lessons around attention rhythms",level:"intermediate",minutes:35,description:"Open with curiosity, alternate instruction with active practice, close with retrieval.",tags:["lesson-planning","pedagogy"],steps:["Hook in first 4 minutes tied to today's objective, not trivia","Direct instruction segments ≤10 minutes before activity switch","Every explanation followed by immediate low-stakes practice","Build checks-for-understanding every segment (cold call safely, mini-whiteboards)","Plan misconception responses in advance, not improv","Close with retrieval: students reconstruct key idea unprompted"],pitfalls:["Beautiful slides doing the learning for students","No planned response to the #1 predictable confusion"]},{id:"course-production-online",title:"Produce an online course people finish",level:"advanced",minutes:45,description:"Structure, pacing, and accountability mechanics fighting the 90% non-completion norm.",tags:["course-design","online-learning"],steps:["Promise one transformation in the title; module = milestone toward it","Videos ≤7 minutes each, one idea per video, show don't only tell","Deliverable after every module learners can share publicly","Weekly rhythm (cohort) or streak mechanics (self-paced) — pick one","First-module win within 30 minutes of signup","Interview finishers AND quitters; fix what quitters cite first"],pitfalls:["Twelve hours of lecture nobody asked to binge","Quizzes testing video recall over applied skill"]}]},{id:"classroom-assessment",label:"Classroom & Assessment",procedures:[{id:"rubric-construction",title:"Build rubrics that grade fairly and fast",level:"intermediate",minutes:30,description:"Analytic rubrics with observable descriptors turning subjective grading into calibrated judgment.",tags:["rubrics","grading","fairness"],steps:["Derive criteria from objectives, max 5 dimensions","Describe each performance level observably ('cites two sources') not adverbially ('excellent')","Pilot on three sample works spanning quality; refine wording collisions","Grade blind where feasible; re-score a 10% sample for consistency","Give rubric to students BEFORE submission, use it for peer/self-checks","Analyze score distributions; a criterion everyone aces is noise"],pitfalls:["Holistic vibes graded differently at 9pm vs fresh morning","Rubrics written after grading to justify scores"]},{id:"behavior-system-design",title:"Design a classroom behavior system that prevents",level:"intermediate",minutes:25,description:"Clear expectations, positive ratios, and least-invasive corrections keeping instruction flowing.",tags:["classroom-management","culture"],steps:["Co-create 3-5 positively-phrased expectations with examples of looks-like","Narrate desired behavior specifically ('tables quieted in 20 seconds')","Aim 4:1 positive-to-corrective interactions minimum, tracked honestly","Least-invasive correction ladder: proximity → private → public consequence","Never debate mid-class; defer conversations to structured 1:1 time","Restart routines after every break like it's week one"],pitfalls:["Public power struggles rewarding the disruption with audience","Rules existing only as poster decoration"]}]}]},{id:"game-interactive",label:"Game & Interactive Dev",icon:"\uD83C\uDFAE",gradient:"from-indigo-400 via-blue-400 to-sky-300",ring:"ring-indigo-500/30",text:"text-indigo-300",blurb:"Gameplay systems, performance budgets, live-ops, and player-experience craft.",roles:["Game Developers","Technical Designers","Live-Ops Engineers","Indie Devs"],domains:[{id:"gameplay-systems",label:"Gameplay Systems",procedures:[{id:"game-feel-tuning",title:"Tune game feel with parameter discipline",level:"intermediate",minutes:35,description:"Juice systems — input buffering, coyote time, screen feedback — tuned via live-adjustable parameters.",tags:["game-feel","juice","tuning"],steps:["Expose movement/combat parameters to a runtime debug panel","Add input buffering (100-150ms) before touching anything else","Add coyote time (~100ms) and jump buffering for platformers immediately","Layer feedback per action: animation, sound, particle, camera nudge, hitstop","Tune one parameter set at a time; record clips comparing before/after","Playtest with controller AND touch/keyboard; feel differs per input"],pitfalls:["Hardcoded magic numbers nobody dares retune","Juice added after systems freeze, breaking balance"]},{id:"save-system-design",title:"Design save systems that survive updates",level:"intermediate",minutes:30,description:"Versioned, forward-compatible saves with migration paths protecting player progress.",tags:["save-data","architecture","live-ops"],steps:["Serialize data by key-value schema with explicit version field","Write migrations as ordered transforms; never assume latest on load","Keep save atomic: write temp + rename to avoid corruption on crash","Cloud-sync conflict policy defined (newest-wins vs merge) and tested","Back up previous save slot automatically before migrating","Test loading every historical version in CI nightly"],pitfalls:["Binary blobs unreadable after class renames","Corrupted-save reports traced to mid-write power loss"]}]},{id:"performance-liveops",label:"Performance & Live-Ops",procedures:[{id:"frame-budget-profiling",title:"Hold frame budgets under real content load",level:"advanced",minutes:40,description:"Per-system millisecond budgets enforced from prototype through ship on target hardware.",tags:["performance","profiling","optimization"],steps:["Set frame budget per platform (e.g., 16.6ms console / 33ms mobile) day one","Allocate sub-budgets: rendering, gameplay logic, physics, UI, audio","Profile weekly on MINIMUM-spec hardware, not dev machines","Fix the top offender only; re-measure; repeat — no speculative optimization","Track draw calls, GC spikes, and load times in CI perf snapshots","Gate releases on budget regressions beyond agreed tolerance"],pitfalls:["Smooth on flagship phones, slideshow on median hardware","GC death spirals from per-frame allocations"]},{id:"live-event-pipeline",title:"Ship live-ops events without client patches",level:"advanced",minutes:45,description:"Server-driven event configuration, remote flags, and staged rollouts keeping content fresh safely.",tags:["live-ops","remote-config","operations"],steps:["Model events as server config consumed by generic client systems","Validate configs against schema + simulation harness before publish","Stage rollout: internal → 5% players → full, with kill switch per feature","Monitor KPIs during events in real-time dashboard with alert thresholds","Rehearse emergency shutdown path quarterly like fire drill","Post-mortem each event: participation, revenue, bug classes, config errors"],pitfalls:["'Small' hotfix patches required per event, defeating live-ops","Timezones ignored, events ending at wrong local hour"]}]}]},{id:"hospitality-travel",label:"Hospitality & Travel",icon:"\uD83C\uDFE8",gradient:"from-amber-500 via-orange-400 to-yellow-300",ring:"ring-amber-500/30",text:"text-amber-400",blurb:"Guest experience craft, service recovery, itinerary design, and revenue-aware operations.",roles:["Hotel & Restaurant Managers","Travel Designers","Guest Experience Teams"],domains:[{id:"guest-experience",label:"Guest Experience",procedures:[{id:"service-recovery-flow",title:"Turn service failures into loyalty",level:"intermediate",minutes:25,description:"Fast acknowledgment, empowered staff, proportionate recovery, and follow-up converting complaints.",tags:["service-recovery","complaints","loyalty"],steps:["Acknowledge within minutes; speed matters more than perfection","Empower frontline staff with recovery budget up to defined limits, no approvals needed","Recover proportionately AND personally — handwritten beats generic upgrade","Fix root cause before the guest departs when possible","Follow up next day with named person, not survey blast","Log failure taxonomy weekly; recurring classes get process fixes"],pitfalls:["Recovery slower than the original failure","Empowerment rhetoric with approval queues in practice"]},{id:"itinerary-design-craft",title:"Design itineraries that feel effortless",level:"intermediate",minutes:35,description:"Energy pacing, transfer buffers, and one anchor per day building trips travelers rave about.",tags:["itineraries","travel-design","planning"],steps:["One anchor experience per day; everything else supports it","Respect jet lag and energy curves for first 48 hours especially","Buffer transfers by measured local reality, not map estimates","Pre-book the unmissable, leave afternoons flexible for weather/mood","Include food logic near activities, not across town","Deliver as scannable day cards with offline maps and confirmation numbers"],pitfalls:["Five 'highlights' per day exhausting everyone","Tight connections built on best-case traffic"]},{id:"review-response-system",title:"Respond to reviews strategically",level:"foundation",minutes:20,description:"Templates + genuine specifics turning public reviews into trust assets.",tags:["reviews","reputation","communication"],steps:["Respond to every review within 48h — positive ones too","Negative: acknowledge specific issue, no excuses, state concrete fix done","Positive: name the staff moment they mentioned; reinforce specifically","Never argue facts publicly; take disputes offline with contact route","Mine monthly themes into operations fixes; mention improvements later ('you asked, we changed')","Track rating trend against response latency"],pitfalls:["Copy-paste replies visible from space","Defensiveness on legitimate complaints going screenshot-viral"]}]},{id:"revenue-operations",label:"Revenue Operations",procedures:[{id:"dynamic-pricing-basics",title:"Apply revenue management without alienating guests",level:"advanced",minutes:40,description:"Demand-based pricing with fences, monitoring, and fairness optics protecting brand.",tags:["pricing","revenue-management","hotels"],steps:["Segment demand: business vs leisure vs event windows behave differently","Set rate tiers with honest fence differences (flexibility, view, timing)","Review pickup pace weekly against same-time-last-year and comp sets","Adjust on leading indicators (search volume, booking pace), not panic","Cap surge multiples; price gouging headlines outlast the revenue","Post-mortem every high-demand window: captured vs left-on-table"],pitfalls:["Static pricing leaving peak revenue unfunded","Loyalty members seeing worse rates than strangers"]},{id:"shift-briefing-ritual",title:"Run shift briefings that actually prepare teams",level:"foundation",minutes:15,description:"Five-minute structured briefings covering arrivals, VIPs, issues, and focus metric.",tags:["operations","briefings","teams"],steps:["Same format daily: arrivals/VIPs, groups, known issues, yesterday's lesson, today's focus","Name specific guests needing extra care with their context","Surface maintenance/aesthetic issues visible to guests today","One service focus theme per shift, not twelve","Close with questions invited explicitly","Rotate who leads so knowledge spreads beyond managers"],pitfalls:["Briefings becoming schedule-readings","VIP context living only in the GM's head"]}]}]},{id:"supply-chain-logistics",label:"Supply Chain & Logistics",icon:"\uD83D\uDE9A",gradient:"from-stone-500 via-zinc-400 to-slate-300",ring:"ring-stone-500/30",text:"text-stone-300",blurb:"Demand planning, inventory policy, supplier management, and disruption resilience.",roles:["Supply Planners","Logistics Managers","Procurement","Operations Analysts"],domains:[{id:"planning-inventory",label:"Planning & Inventory",procedures:[{id:"demand-baseline-forecast",title:"Build a demand baseline you can beat",level:"intermediate",minutes:35,description:"Cleanse history, segment by variability, and benchmark naive forecasts before fancy models.",tags:["forecasting","demand-planning"],steps:["Cleanse history: mark stockouts, promotions, one-time events explicitly","Segment SKUs by ABC volume \xd7 XYZ variability — different methods per class","Benchmark naive (last period / same-period-last-year) first, always","Only adopt complex methods that beat naive on YOUR data out-of-sample","Forecast at the grain decisions are made; aggregate for reporting only","Track bias separately from accuracy; systematic over/under is fixable"],pitfalls:["Promotional spikes trained into base demand forever","MAPE worship while every forecast runs systematically high"]},{id:"safety-stock-policy",title:"Set safety stock from service targets and real variability",level:"intermediate",minutes:30,description:"Statistical buffers per SKU-class matching stated service levels and lead-time truth.",tags:["inventory","safety-stock","service-level"],steps:["Get REAL lead times: quoted vs actual distribution, not PO text","Set service levels deliberately by segment (A items higher than C)","Compute buffers from demand AND lead-time variability together","Review exceptions monthly: expedites and stockouts reveal policy misses","Cap total buffer investment; trade service level against working capital explicitly","Recalculate quarterly; yesterday's volatility isn't tomorrow's"],pitfalls:["One blanket weeks-of-supply rule across all SKUs","Buffers hiding chronic supplier reliability problems"]},{id:"disruption-playbook",title:"Write a disruption playbook before you need it",level:"advanced",minutes:40,description:"Pre-ranked responses to supplier/port/demand shocks with decision authority mapped.",tags:["resilience","risk","continuity"],steps:["Map single-source dependencies and their revenue exposure honestly","Pre-qualify alternates for critical single-sourced inputs NOW","Define trigger thresholds per scenario with named decision owners","Rank responses: buffer draw-down → alternate source → allocation → price action","Rehearse one scenario annually as tabletop with data available","Post-event review updates thresholds and contacts list"],pitfalls:["Contact lists outdated when the port actually closes","Playbooks written post-crisis and never tested"]}]},{id:"suppliers-freight",label:"Suppliers & Freight",procedures:[{id:"supplier-scorecards",title:"Manage suppliers with balanced scorecards",level:"intermediate",minutes:30,description:"OTIF, quality, responsiveness, and cost trends driving development or exit decisions.",tags:["supplier-management","procurement","scorecards"],steps:["Measure OTIF (on-time in-full) from need date, not promised date","Add quality PPM and corrective-action response time to the card","Weight dimensions by category strategy, not one-size formula","Share scorecards with suppliers quarterly — surprises are failures","Tie score bands to concrete consequences: volume growth or exit path","Track trend direction; one bad quarter ≠ chronic underperformer"],pitfalls:["Scorecards measuring only price variance","Top offenders kept because switching is annoying"]},{id:"freight-cost-audit",title:"Audit freight costs beyond invoice approval",level:"foundation",minutes:25,description:"Accessorial charges, mode mix, and lane benchmarking recovering recurring overspend.",tags:["freight","logistics","cost-reduction"],steps:["Reconcile invoices against rated quotes automatically where possible","Pareto accessorials: detention and reweight usually dominate recoverables","Analyze mode misuse: air freight that missed a boat by two days","Benchmark top lanes against market indices quarterly","Fix root causes: packaging specs reducing dim-weight rewrites","Claim recoverable charges within carrier contract windows religiously"],pitfalls:["Approving invoices without rate verification ever","Accessorials treated as noise rather than signal"]}]}]},{id:"nonprofit-impact",label:"Nonprofit & Impact",icon:"\uD83C\uDF0D",gradient:"from-teal-600 via-green-500 to-lime-400",ring:"ring-teal-500/30",text:"text-teal-300",blurb:"Theory of change, donor stewardship, program measurement, and board effectiveness.",roles:["Nonprofit Leaders","Program Managers","Fundraisers","Board Members"],domains:[{id:"strategy-measurement",label:"Strategy & Measurement",procedures:[{id:"theory-of-change-map",title:"Map a theory of change stakeholders believe",level:"intermediate",minutes:40,description:"Inputs to long-term outcomes with assumptions surfaced and testable, not poster decoration.",tags:["theory-of-change","strategy","impact"],steps:["Start from the long-term outcome in beneficiaries' terms, not activity counts","Work backwards: preconditions required at each prior step","State EVERY assumption explicitly with evidence strength rating","Identify the riskiest assumption — that's your first evaluation target","Define indicators per link, mixing output + outcome measures","Review annually against reality; revise proudly, not reluctantly"],pitfalls:["Logic models listing activities while calling them outcomes","Assumptions invisible until evaluation 'fails' mysteriously"]},{id:"impact-measurement-framework",title:"Measure impact without drowning programs",level:"advanced",minutes:45,description:"Lightweight data collection embedded in delivery producing credible outcome claims.",tags:["measurement","m-and-e","outcomes"],steps:["Pick 5-8 indicators max tied to theory-of-change links","Embed collection into existing touchpoints; separate surveys die","Baseline before program contact wherever feasible","Pair quantitative outcomes with two qualitative depth stories","Report negative and null findings honestly — funders trust this","Calculate cost-per-outcome once baseline exists; revisit yearly"],pitfalls:["Counting attendance as impact","Data collected for funders never used by programs"]}]},{id:"fundraising-governance",label:"Fundraising & Governance",procedures:[{id:"donor-stewardship-tiers",title:"Steward donors by relationship tier",level:"intermediate",minutes:35,description:"Segmented thank-you speed, reporting rhythm, and upgrade paths treating donors as partners.",tags:["donors","stewardship","fundraising"],steps:["Thank within 48 hours for everyone; major gifts get a call from leadership","Segment by capacity \xd7 affinity, not just last gift size","Report impact BEFORE next ask, on a promised rhythm kept","Invite mid-tier into insider experiences (site visits, briefings) deliberately","Track second-gift conversion as the health metric that matters most","Lapse analysis quarterly: what changed before giving stopped?"],pitfalls:["Silence between asks read as indifference","Major donor treated identically to email-list donor"]},{id:"board-effectiveness-audit",title:"Audit board effectiveness honestly",level:"foundation",minutes:30,description:"Roles, composition, meeting design, and give/get expectations aligned to actual strategy needs.",tags:["governance","boards","leadership"],steps:["Map current skills vs strategy needs (finance? legal? community voice?)","Clarify fiduciary vs advisory roles in writing for every member","Design meetings for decisions: consent agendas, pre-reads, one big question","Set explicit give/get expectations asked at recruitment, revisited annually","Run self-assessment yearly with anonymous input","Recruit to gaps with real role descriptions, not warm-body fills"],pitfalls:["Boards micromanaging operations while skipping fiduciary duty","Meeting time consumed by staff reports over decisions"]}]}]},{id:"sports-performance",label:"Sports & Performance",icon:"\uD83C\uDFC6",gradient:"from-orange-600 via-amber-400 to-lime-400",ring:"ring-amber-500/30",text:"text-amber-300",blurb:"Training design, load monitoring, and return-to-play progression for coaches and athletes.",roles:["Coaches","S&C Specialists","Athletic Trainers","Team Scientists"],domains:[{id:"training-design",label:"Training Design",procedures:[{id:"periodization-basics",title:"Periodize training around real competition calendars",level:"intermediate",minutes:35,description:"Macro-to-micro planning balancing stress and adaptation with planned recovery weeks.",tags:["periodization","planning","coaching"],steps:["Anchor to competition dates working backwards through phases","Define each phase's primary adaptation goal in one sentence","Vary volume and intensity inversely within weeks, not both up together","Plan deload every 3-5 weeks BEFORE fatigue forces it","Individualize: adjust for athletes' life stress and sleep reality","Review block outcomes against phase goals; carry lessons forward"],pitfalls:["Copy-pasting elite programs onto developing athletes","Competition prep starting after it should have"]},{id:"load-monitoring-practical",title:"Monitor training load without gadget worship",level:"foundation",minutes:25,description:"Simple consistent measures — sRPE, duration, wellness — trended per athlete over time.",tags:["load-management","monitoring","safety"],steps:["Collect session RPE \xd7 minutes within 30min post-session, consistently","Compute acute (7d) vs chronic (28d) ratio; flag spikes above agreed band","Add one subjective wellness signal daily (sleep/soreness/mood scale)","Trend INDIVIDUALLY; population averages hide the athlete at risk","Act on flags via conversation first, dashboards second","Review monitoring usefulness each season; delete vanity metrics"],pitfalls:["ACWR treated as physics instead of a rough flag","Data collected but never changing tomorrow's session"]},{id:"return-to-play-progression",title:"Progress return-to-play by criteria, not calendars",level:"advanced",minutes:40,description:"Stage gates with objective tests protecting athletes from rush-back reinjury.",tags:["rehabilitation","return-to-play","safety"],steps:["Define stage criteria BEFORE injury happens where possible","Each stage: pain-free capacity → sport-specific loads → reactive chaos","Test objectively per stage (strength symmetry, hop tests, speed percentages)","Progress on criteria met, never on schedule pressure alone","Include psychological readiness — fear of reinjury predicts actual risk","Full clearance requires full training week completed symptom-free"],pitfalls:["Calendar-based clearances driven by fixture pressure","Skipping the final 'chaos' stage straight into competition"]}]},{id:"coaching-craft",label:"Coaching Craft",procedures:[{id:"effective-cueing",title:"Cue movements so they actually change",level:"foundation",minutes:20,description:"External-focus cues, one fix at a time, and demonstration pairing accelerating skill acquisition.",tags:["coaching","motor-learning","communication"],steps:["Prefer external focus ('push the floor away') over joint anatomy talk","One cue per attempt; stacked instructions freeze learners","Show AND say for novices; fade demonstrations as skill grows","Reinforce what's right specifically before correcting what's off","Check understanding: ask them to tell you the fix in their words","Retire cues that stopped producing change; rotate metaphors"],pitfalls:["Anatomical lectures mid-set","Same ineffective cue repeated louder"]},{id:"warmup-that-prepares",title:"Design warm-ups that prepare, not tire",level:"foundation",minutes:15,description:"Progressive raise-activate-mobilize structure specific to the session's demands.",tags:["warm-up","preparation","injury-prevention"],steps:["Raise: 3-5min general pulse elevation appropriate to intensity ahead","Activate: target the day's key muscle groups with light loaded work","Mobilize: dynamic ranges matching sport positions, not static holding","Potentiate: ramp sport-specific intensity ending near working pace","Total 10-15 minutes; fatigue is failure, sweat is success","Adapt content to session focus — leg day ≠ upper day prep"],pitfalls:["20 minutes of static stretching before sprint work","Generic jog-and-stretch ignoring the day's actual demands"]}]}]},{id:"media-production",label:"Media & Video Production",icon:"\uD83C\uDFAC",gradient:"from-sky-600 via-blue-500 to-indigo-400",ring:"ring-sky-500/30",text:"text-sky-400",blurb:"Pre-production discipline, interview craft, edit pacing, and publish-ready packaging.",roles:["Video Creators","Podcasters","Documentary Makers","Content Studios"],domains:[{id:"preproduction",label:"Pre-Production",procedures:[{id:"prepro-checklist",title:"Pre-produce shoots that don't improvise",level:"foundation",minutes:30,description:"Shot lists, location scouts, gear checks, and contingency plans making shoot days boring.",tags:["pre-production","planning","video"],steps:["Write the one-sentence deliverable definition before anything else","Shot list from the edit backwards: every shot has a destination","Scout locations at shoot TIME of day for light and noise reality","Gear checklist per shot type; batteries and media double what seems enough","Contingency plan per risk: weather, noise, subject cancellation","Confirm everyone 24h before with call sheet including parking/access notes"],pitfalls:['"We\'ll figure it out there" burning golden-hour hours',"Missing B-roll discovered in the edit"]},{id:"interview-setup-craft",title:"Set up interviews that produce usable answers",level:"intermediate",minutes:35,description:"Question design, comfort engineering, and listening technique yielding complete soundbites.",tags:["interviews","documentary","storytelling"],steps:["Research enough to ask unexpected second questions","Open with throwaway comfort questions while checking levels","Ask one idea per question ending with open phrasing","Embrace silence after answers; the second take is usually gold","Request the story, not the opinion ('walk me through that day')","Re-ask key answers cleanly once rapport peaks for edit-friendly takes"],pitfalls:["Yes/no questions producing unusable fragments","Interrupting the pause where real answers live"]}]},{id:"post-publish",label:"Post & Publishing",procedures:[{id:"edit-pacing-discipline",title:"Edit with ruthless pacing discipline",level:"intermediate",minutes:40,description:"Structure-first assembly, kill-your-darlings trims, and audio polish before visual candy.",tags:["editing","pacing","post-production"],steps:["Assemble radio-cut (audio only) first; if story works deaf, visuals elevate","Trim each clip to its strongest start and end — then trim again","Vary rhythm deliberately: pattern breaks hold attention","Fix audio quality before color; bad audio reads as amateur instantly","Watch full cut on phone speaker AND headphones before sharing","Cut your favorite shot if it doesn't serve the story — really"],pitfalls:["Effects compensating for structure problems","Ten-second intros before value appears"]},{id:"publish-packaging",title:"Package publishes for discovery",level:"foundation",minutes:25,description:"Titles, thumbnails, descriptions, and chapters engineered as a system per platform.",tags:["packaging","youtube","distribution"],steps:["Title promises specific payoff; thumbnail shows tension or outcome, minimal text","Test title/thumbnail as a pair — they argue or agree as one unit","First line of description restates the promise for search","Chapters named by content curiosity, not 'Part 1'","Adapt aspect ratio, length, and hook timing per platform natively","Log packaging hypotheses with results; build your own playbook"],pitfalls:["Same file cross-posted everywhere identically","Thumbnail text unreadable at feed size"]}]}]}]}};